(window.RAGHIB_FULL = window.RAGHIB_FULL || {})["3-2"] = [{"a": [48, 49], "v": 2, "p": 570, "ev": 2, "ep": 577, "sid": 772, "t": "قوله عز وجل: (ويعلمه الكتاب والحكمة والتوراة والإنجيل (48) ورسولا إلى بني إسرائيل أني قد جئتكم بآية من ربكم أني أخلق لكم من الطين كهيئة الطير فأنفخ فيه فيكون طيرا بإذن الله وأبرئ الأكمه والأبرص وأحي الموتى بإذن الله وأنبئكم بما تأكلون وما تدخرون في بيوتكم إن في ذلك لآية لكم إن كنتم مؤمنين (49)\nالهيئة: الحالة المحسوسة التي تحدث للشيء، والهيء: الحسن\nالهيئة، ومنها أخذ المهايأة فيما يتراضى به على وجه التخمين.\nوالنفخ: جعل الريح في الشيء ومنه النفخة، وعنه استعير نفخة\nالصور، والنفخة للورم تشبيها بما ينفخ فيه، والنفاخة للحجاة.\nوالادخار: افتعال من الذخر وهو إعداد الشيء لنائبة قال\n⟦2:571⟧\nالفراء: قرئ (تدخرون) خفيفة، وقال بعض العرب:\n(تذخرون) فعوقب بين الذال والدال نحو تدكر وتذكر.\nوالأكمه: الذي ولد أعمى.\nوقول الحسن: الأكمه الأعمى صحيح، وكل كمه عمى، وإن لم يكن كل عمى كمها.\nوقول مجاهد: الأكمه الذي لا يبصر بالليل دون النهار، فليس بشيء،\n⟦2:572⟧\nوقوله: ﴿وَيُعَلِّمُهُ ٱلۡكِتَٰبَ﴾⟪3:48⟫ يجوز أن يعني بحال طفوليته إن\nقيل: كيف ذكر الكتاب، ثم عطف عليه التوراة والإنجيل، وهما\nمن جملة الكتاب؟\nقيل: قالوا: عنى بالكتاب القراءة والكتابة، وعلم تعليما إلاهيا في حال الطفولية، وقيل: عنى بالكتاب كتب الله المنزلة وخصص التوراة والإنجيل كتخصيص ذكر جبريل وميكائيل بعد الملائكة تفضيلا لهم، وقد تقدم الفرق\n⟦2:573⟧\nبين الكتاب والحكمة، وقرئ و (يعلمه) عطفا على قوله:\n﴿كَذَٰلِكِ ٱللَّهُ يَخۡلُقُ﴾⟪3:47⟫، وبالنون عطفا على قوله: ﴿ذَٰلِكَ مِنۡ أَنۢبَآءِ ٱلۡغَيۡبِ نُوحِيهِ﴾، وقوله: (ورسولا) عطف على قوله: (وجيها) وقيل تقديره: ويجعله رسولا\n⟦2:574⟧\nإن قيل: كيف تعلق هذه الآية بما قبلها، وما قبلها حكاية حكى\nالله عن نفسه، وهو: (ويعلمه الكتاب)، وهذه حكاية حكاها\nعن عيسى عليه الصلاة والسلام، وهو ﴿أَنِّي قَدۡ جِئۡتُكُم﴾⟪3:49⟫\nقيل: تقديره: وبعث رسولا يقول: إني قد جئتكم، ودل على إضمار\nالقول ذكر الر سول وترك ذكر مريم، وابتدأ بإرسال عيسى، وما\nقال له، وذكر معجزاته.\nإن قيل: لم ذكر في الخلق وفي إحياء الموتى (بإذن الله).\nولم يذكر في غيرهما؟\nقيل: لكون هذين الفعلين إلاهيين، لم يجعل للمخلوقين إليهما سبيلا.\nبخلاف النفخ والمداواة والإخبار ببعض الغيب، فقد جعل للإنسان كثيرا من\nالمداواة، وجعل لهم شيئا من الإخبار بالغيب كالفراسة\n⟦2:575⟧\nوالإلهام ولم يجعل لهم الخلق ولا إحياء الموتى، فنبه بقوله:\n﴿بِإِذۡنِ ٱللَّهِۖ﴾⟪3:49⟫ أن ذلك فعل في الحقيقة صادر منه تعالى، وإن\nكان يظهر من غيره كالفراسة والمداواة، وإن كانا قد يحصلان من\nسائر البشر، فذلك قد يكون باعتماد على تجربة واعتبار أمر.\nولا يكون في كل وقت وعلى كل حال، ولا في دفعة واحدة.\nوما كان يفعله عيسى كان بخلاف فعل البشر، فلهذا كان معجزة،\n⟦2:576⟧\nوقوله: ﴿إِن كُنتُم مُّؤۡمِنِينَ﴾⟪3:49⟫ أن المؤمن هو الذي يتفكر في\nذلك، فتحصل له الآية.\nوقرىء (إني) على الاستئناف، ويكون تفسيرا للآية.\nكما أن قوله: ﴿لَهُم مَّغۡفِرَةٞ﴾ تفسير للوعد.\nوإذا قرىء (أني) بالفتح، فعلى تقدير الجر بدلا من آية\nأو على قدر الرفع خبر ابتداء مضمر، كأنه قال: الآية\n⟦2:577⟧\nأني قد جئتكم."}, {"a": [50], "v": 2, "p": 577, "ev": 2, "ep": 581, "sid": 779, "t": "قوله عز وجل: (ومصدقا لما بين يدي من التوراة ولأحل لكم بعض الذي حرم عليكم وجئتكم بآية من ربكم فاتقوا الله وأطيعون (50)\nفقوله: ومضدقا معطوف على ما دل عليه\nقوله: (بآية من ربكم أني قد جئتكم) مستصحبا آية، ومصدقا.\nكقولك: جئتك بما تحب ومكرما لك، وليس بمعطوف على\n(وجيها) ولا (رسولا)، لقوله: ﴿لِّمَا بَيۡنَ يَدَيَّ﴾⟪3:50⟫ أني أحقق ما أتيت\nبه من التوراة، فيكون ذلك معدودا من جملة معجزاته.\nوقال قتادة والربيع\n⟦2:578⟧\nوابن جريج؟ كان المحرم عليهم في شريعة موسى لحوم الإبل\nوالأشياء من الطير والحيتان، فاحلها عيسى لهم.\nوقال أبو عبيدة: عنى ببعض الذي حرم الكل، واحتج بقوله:\n⟦2:579⟧\n. . أو يرتبط بعض النفوس حمامها\nوقال الزجاج: هذا فاسد، لأن البعض لا يكون، بمعنى الكل.\nوعنى لبيد ببعض النفوس نفسه خاصة فعرض.\nولأن عيسى حلل بعض المحرمات، وهو الذي كانوا حرموا على أنفسهم،\n⟦2:580⟧\nوقوله: (ولأحل) معطوف على موضع (ومصدقا) لأن تقديره:\nلأصدق ولأحل، كقولك: جئتك معتذرا ولأطيب قلبك.\nوعلى ذلك تقدير قوله: ﴿وَكَذَٰلِكَ نُرِيٓ إِبۡرَٰهِيمَ مَلَكُوتَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلِيَكُونَ مِنَ ٱلۡمُوقِنِينَ﴾⟪6:75⟫.\nوقوله: ﴿وَجِئۡتُكُم بِـَٔايَةٖ﴾⟪3:50⟫ ف ي قراءة عبد الثه (آيات) في\nالموضعين، وإنما لم يقل: من ربي أو ربنا. لأن ذلك أخص من المخاطبين.\nوقوله: ﴿فَٱتَّقُواْ ٱللَّهَ﴾⟪3:50⟫ قيل: وحدوا الله.\nوتقواه أخص من توحيده، إذ هي مبنية عليه.\nودعاؤه إلى طاعته دعاء\n⟦2:581⟧\nفيما دعاهم إليه من تقوى الله."}, {"a": [51], "v": 2, "p": 581, "ev": 2, "ep": 581, "sid": 783, "t": "قوله عز وجل: (إن الله ربي وربكم فاعبدوه هذا صراط مستقيم (51)\nلما وصف عيسى نفسه بأفعال إلهية، وأتى على ما ذكر.\nوكان قد قال: (وأطيعون) خطر له ما فعلته جماعة من\nالنصارى، وهو اتخاذهم إياه معبودهم، فقال: ﴿إِنَّ ٱللَّهَ رَبِّي وَرَبُّكُمۡ﴾⟪3:51⟫\nولم يقل: ربنا، ليكون أبعد من التأويل فيما ادعوه.\nوأمر بأن يعبد الله وحده، وقال: ﴿هَٰذَا صِرَٰطٞ مُّسۡتَقِيمٞ﴾⟪3:51⟫ تنبيها\nأن العدول عن ذلك ليس بالمستقيم."}, {"a": [52], "v": 2, "p": 581, "ev": 2, "ep": 585, "sid": 783, "t": "قوله عز وجل: (فلما أحس عيسى منهم الكفر قال من أنصاري إلى الله قال الحواريون نحن أنصار الله آمنا بالله واشهد بأنا مسلمون (52)\nالإحساس: الوجود بالحاسة، وحسه: قتله، كأنه أصاب حسه نحو قلبه وبطنه، وقال الفراء : يقال\nحسست، وحسست، وحسيت وأحست، فأما حسسته\n⟦2:582⟧\nفأصبته بحاستي نحو: عنته ويديته أي أصبته بهما.\nفأما حسست، فنحو علمت وفهمت، وأما حسيت فبقلب إحدى\nالسينين ياء، وأما أحست فبحذف، إحداهما نحو: ظلت في\nظللت، وكلا اللغتين تحريا للتخفيف، وإنما قال: ﴿فَلَمَّآ أَحَسَّ﴾⟪3:52⟫ دون علم تنبيها أنه ظهر منهم الكفر ظهورا باديا لذي الحاسة فضلا لذي العقل.\nوقوله: ﴿إِلَى ٱللَّهِۖ﴾⟪3:52⟫ أي\n⟦2:583⟧\nمتوجها إلى الله، وقيل: مع الله نحو الذود إلى الذود إبل.\nوقيل: لئه، نحو ﴿أَفَمَن يَهۡدِيٓ إِلَى ٱلۡحَقِّ﴾⟪10:35⟫ والوجه هو الأول.\nوالأنصار جمع نصير - نحو: أشهاد في جمع شهيد، والحواريون\nقيل: سموا لبياض ثيابهم، عن ابن جبير، وقال بعضهم:\n⟦2:584⟧\nعنى ببياض ثيابهم نقاء نفوسهم، نحو ﴿وَثِيَابَكَ فَطَهِّرۡ﴾⟪74:4⟫.\nوقولهم: فلان طاهر الثوب، وفي ضده: دنس الثوب.\nوقيل: كانوا قصارين يبيعون الثياب.\nوقال بعضهم: عنى أنهم كانوا يطهرون نفوس الناس.\nوقول النبي - صلى الله عليه وسلم -: \"الزبير ابن عمتي\nوحواري \" تشبيها بهم، وقول أبي عبيدة: الحواريون صفوة\n⟦2:585⟧\nالأنبياء فنظر منه إلى حواري عيسى عليه السلام، وإلى قول\nالنبي - صلى الله عليه وسلم -، وقد تقدم القول في الإيمان والإسلام، وعنى بالإسلام ها هنا الاستسلام لله عز وجل، كقول إبراهيم:\n﴿أَسۡلَمۡتُ لِرَبِّ ٱلۡعَٰلَمِينَ﴾⟪2:131⟫."}, {"a": [53], "v": 2, "p": 585, "ev": 2, "ep": 587, "sid": 787, "t": "قوله تعالى: (ربنا آمنا بما أنزلت واتبعنا الرسول فاكتبنا مع الشاهدين (53).\n⟦2:586⟧\nالاتباع: الاقتداء بالمتبع، وهو أخص من الإجابة، إذ قد\nيكون مجيبا من لا يكون تابعا، وإنما قال: (ربنا) ولم يقل:\nرب العباد؛ لأن الموضع موضع اعتراف وشكر، لا الإخبار عما\nعليه الشيء في نفسه، فلذلك خص (ربنا)، وقد تقدم أن الشاهد\nهو المخبر عن الشيء مشاهدة: إما حسا أو عقلا، وأنه استعير\nللشهادة في الأحكام، والشاهدون ها هنا هم الذين على طريقة\nمن قال فيهم: ﴿لِّتَكُونُواْ شُهَدَآءَ عَلَى ٱلنَّاسِ﴾⟪2:143⟫.\nونبه بقوله: ﴿فَٱكۡتُبۡنَا مَعَ ٱلشَّٰهِدِينَ﴾⟪3:53⟫ أنهم منهم،\n⟦2:587⟧\nوقوله: (ربنا) متصل بالحكاية عنهم.\nوأخبرنا تعالى بذلك لنقتدي بهم في متابعة\nالنبي - صلى الله عليه وسلم - والتضرع إلى الله في طلب الثواب كما طلبوه."}, {"a": [54], "v": 2, "p": 587, "ev": 2, "ep": 590, "sid": 789, "t": "قوله عز وجل. (ومكروا ومكر الله والله خير الماكرين (54)\nالمكر في الأصل: حيلة يجلب بها الإنسان إلى مفسدة.\nوحيلة قد تقال فيما يجلب به إلى مصلحة، وقد يقال في ذلك المكر\nوالخديعة اعتبارا بظاهر الفعل دون المقصد، والحكيم قد يفعل\nما صورته صورة المكر، ولكن قصده المصلحة لا المفسدة، وعلى\nهذا سئل بعض المحققين عن مكر الله فأنشد:\n⟦2:588⟧\nويقبح من سواك الشيء عندي. . . وتفعله فيحسن منك ذاكا\nفإذن مكر الله قد يكون تارة فعلا يقصد به مصلحة، ويكون تارة\nجزاء المكر، ويكون تارة بأن لا يقبح مكرهم في عينهم، وذاك\nبانقطاع التوفيق عنهم وتزيين ذلك في أعينهم، حتى كأنه زينه في\nأعينهم ومكر بهم، ويكون تارة بإعطائهم ما يريدون من دنياهم.\nفإذا أعطاهم واستعملوه على غير ما يحب، فكأنه مكر بهم،\n⟦2:589⟧\nواستدرجهم من حيث لا يعلمون.\nولأجله قال: ﴿وَهُوَ شَدِيدُ ٱلۡمِحَالِ﴾⟪13:13⟫\nوهذا من المعنى الذي اقتضى الذي قال تعالى:\n﴿وَيُحَذِّرُكُمُ ٱللَّهُ نَفۡسَهُۥۗ﴾\nوقال الكلبي: مكرهم كان تدبيرهم في قتل عيسى (ومكر الله) أنه ألقى شبه عيسى\n⟦2:590⟧\nعلى رجل كان يقال له يهوذا عهد لقتل عيسى، فدخل بيتا فظن\nأن عيسى عليه الصلاة السلام فيه فتبعه القوم فصلبوه.\nوقال الأصم: مكره بهم أن سلط عليهم فارس، فقتلوهم، وسبوا\nذراريهم، لقوله: ﴿بَعَثۡنَا عَلَيۡكُمۡ عِبَادٗا﴾⟪17:5⟫."}, {"a": [55], "v": 2, "p": 590, "ev": 2, "ep": 595, "sid": 792, "t": "قوله تعالى: (إذ قال الله يا عيسى إني متوفيك ورافعك إلي ومطهرك من الذين كفروا وجاعل الذين اتبعوك فوق الذين كفروا إلى يوم القيامة ثم إلي مرجعكم فأحكم بينكم فيما كنتم فيه تختلفون (55)\nإن قيل: كيف قال: ﴿إِنِّي مُتَوَفِّيكَ﴾⟪3:55⟫ وقد قال تعالى: ﴿وَمَا قَتَلُوهُ وَمَا صَلَبُوهُ﴾⟪4:157⟫؟ قيل: جملة الأمر أن ليس في\n⟦2:591⟧\nذلك منافاة، إذ ليس كل متوفى يكون مقتولا.\nوقد قال الفراء: معناه: ورافعك إلي ومتوفيك، فقدم وأخر.\nوقال الربيع: توفاه، ووفاته النوم.\nوقال غيرهما: آخذك وافيا لم ينقص منك شيء.\nوقال الحسن: وفاة الرفع، لا وفاة الموت.\n⟦2:592⟧\nوقال ابن عباس ووهب: وفاة موت، فإنه أماته ثم أحياه فرفعه.\nوقال بعضهم: معنى متوفيك آخذك عن هواك، ورافعك إلي عن\nشهوتك، ولم يكن ذلك رفعا مكانيا، وإنما هو رفعة المحل \"،\n⟦2:593⟧\nوإن كان قد رفع إلى السماء، وعلى هذا قوله تعالى: ﴿وَرَفَعۡنَٰهُ مَكَانًا عَلِيًّا﴾⟪19:57⟫ وتطهيره من الكافرين إخراجه من بينهم.\nوقيل: تخليصه من قتلهم، لأن ذلك طهرة منه.\nوقوله: ﴿فَوۡقَ ٱلَّذِينَ كَفَرُوٓاْ﴾⟪3:55⟫ أي فوقهم بالبرهان والحجة.\nوقال ابن زيد: عنى أنه جعل النصارى فوق اليهود في العزة.\nفقد جعل لهم مملكة ولم يجعلها لليهود.\nوقيل: عنى بقوله: ﴿وَجَاعِلُ ٱلَّذِينَ ٱتَّبَعُوكَ﴾⟪3:55⟫:\n⟦2:594⟧\nمن اتبع نبينا عليه الصلاة والسلام منهم، فإن من لم يتبعه بعد\nبعثته فهو في الحقيقة غير تابع لعيسى، وقيل: معنى قوله:\n⟦2:595⟧\nفوقهم: أي يوم القيامة في الجنة، إذ هم في الغرفات آمنون.\nوالذين كفروا في أسفل السافلين!\nوحينئذ تتعلق (إلى) بما تقدم، وقد تقدم الكلام في الرجوع إلى الله."}, {"a": [56], "v": 2, "p": 595, "ev": 2, "ep": 596, "sid": 797, "t": "قوله عز وجل: (فأما الذين كفروا فأعذبهم عذابا شديدا في الدنيا والآخرة وما لهم من ناصرين (56)\nتعذيب الله الكفار\n⟦2:596⟧\nوالأشرار في الدنيا ضربان: ضرب عرفوه عذابا كالأمراض\nوالخسف والمسخ وتسليط المؤمنين عليهم.\nوضرب حسبوه نعمة وهو في الحقيقة نقمة.\nوذلك كتمكينهم من مال وجاه وسائر أعراض الدنيا، التي حظهم منها الهموم والغموم، وإياه عنى بقوله: ﴿إِنَّمَا يُرِيدُ ٱللَّهُ أَن يُعَذِّبَهُم بِهَا فِي ٱلدُّنۡيَا﴾⟪9:85⟫."}, {"a": [57], "v": 2, "p": 596, "ev": 2, "ep": 597, "sid": 798, "t": "قوله عز وجل: (وأما الذين آمنوا وعملوا الصالحات فيوفيهم أجورهم والله لا يحب الظالمين (57)\nالإيمان: فعل ما يقتضي الأمن من عذاب الله.\nوالصلاح: فعل ما يقتضي الصلح بينه وبين الله عز وجل.\nوالتوفية: إعطاؤه ما لا ينقص عما يقابلبه،\n⟦2:597⟧\nوالإيفاء الزيادة عليه، إن قيل: كان من حق المقابلة أنه لما عاقب\nذكر الكافرين بقوله: ﴿وَمَا لَهُم مِّن نَّٰصِرِينَ﴾⟪3:56⟫ أن يذكر ها هنا ما\nينافيه فيقول: ﴿وَٱللَّهُ وَلِيُّ ٱلۡمُؤۡمِنِينَ﴾⟪3:68⟫. ونحو ذلك من الكلام لا قوله:\n﴿وَٱللَّهُ لَا يُحِبُّ ٱلظَّٰلِمِينَ﴾⟪3:57⟫.\nقيل: إن قوله: ﴿وَٱللَّهُ لَا يُحِبُّ ٱلظَّٰلِمِينَ﴾⟪3:57⟫ من صفة الذين كفروا.\nونبه بالصفتين جميعا، أعنى هذه وقوله: ﴿وَمَا لَهُم مِّن نَّٰصِرِينَ﴾⟪3:56⟫ على كون المؤمنين منصورين ومحبوبين.\nوقد دل على ذلك من فحوى الكلام في هذه الآية وغيرها من\nالآيات، وفي قوله: ﴿لَا يُحِبُّ ٱلظَّٰلِمِينَ﴾⟪3:57⟫ تنبيه أنه لا يظلم خلقه.\nفمن لا يحب شيئا لا يتعاطاه مع استغنائه عنه.\nإن قيل: ما وجه إعادة ذكر عذاب الكافرين وثواب المؤمن العاقل الصالح في هذا المكان؟\nقيل: إن ذلك مقترن بمخاطبته عيسى، وهو قوله: ﴿إِنِّي مُتَوَفِّيكَ﴾⟪3:55⟫\nوتقديره: الذين كفروا بك، آمنوا بك. لكن حذف ذلك اختصار."}, {"a": [58], "v": 2, "p": 598, "ev": 2, "ep": 599, "sid": 800, "t": "قوله عز وجل: (ذلك نتلوه عليك من الآيات والذكر الحكيم (58)\nالتلاوة والتنزيل والقص متقارب، لكن يقال:\nالتلاوة اعتبارا بمساوقة بعض الكلام بعضا بالولاء، والإنزال\nاعتبارا بإخبار الأعلى الأدون، والأرفع للأوضع.\nوالقص اعتبارا باقتطاع الخبر على ما هو به، وقص أثره.\nوالحكيم: المحكم، إشارة إلى قوله: ﴿أُحۡكِمَتۡ ءَايَٰتُهُۥ﴾⟪11:1⟫.\nويجوز أن يكون بمعنى فاعل، كأنه ناطق بالحكمة وفاعل لها، لا لاقتضائه إياها.\nوقوله: (ذلك): مبتدأ، و (نتلوه): خبره، وقيل: ذلك تقديره:\nالذي، و (نتلوه): صلته، والخبر قوله ﴿مِنَ ٱلۡأٓيَٰتِ﴾⟪3:58⟫\n⟦2:599⟧\nوتلاوته: إنزاله، ويجوز أن تجعل تلاوة جبريل والنبي - صلى الله عليه وسلم - وأوليائه تلاوة لما كان بأمره، فأفعال أوليائه قد تنسب إليه، كقوله\nعز وجل: ﴿ٱللَّهُ يَتَوَفَّى ٱلۡأَنفُسَ حِينَ مَوۡتِهَا﴾⟪39:42⟫.\nوقوله في موضع آخر: ﴿قُلۡ يَتَوَفَّىٰكُم مَّلَكُ ٱلۡمَوۡتِ﴾⟪32:11⟫."}, {"a": [59], "v": 2, "p": 599, "ev": 2, "ep": 603, "sid": 801, "t": "قوله عز وجل: (إن مثل عيسى عند الله كمثل آدم خلقه من تراب ثم قال له كن فيكون (59)\nلما ذكر تعالى مكان عيسى من الفضيلة، وما آتاه من المنزلة.\nكذب النصارى فيما ادعوه من بنوته،\n⟦2:600⟧\nوبين كيفية خلقه من غير ذكر.\nإن قيل: كيف يكون عيسى مثل آدم وآدم لم يضمه رحم؟\nقيل: إن ذلك تكذيب للنصارى فيما ادعوه.\nوذلك أن أهل نجران قالوا: ما رأينا ابنا بلا أب؟\nفأنزل الله ذلك تبيينا: أن ليس أمر عيسى بأعجب من أمر آدم.\nإذ هو لم يخلق من ذكر ولا أنثى وعلى نحوه دل قوله:\n﴿أَوَلَيۡسَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِقَٰدِرٍ عَلَىٰٓ أَن يَخۡلُقَ مِثۡلَهُمۚ﴾⟪36:81⟫.\nإن قيل: لم قال: ﴿عِندَ ٱللَّهِ﴾⟪3:59⟫. أهو يشبهه عند الله دون غيره؟\nقيل: عنى بقوله: ﴿عِندَ ٱللَّهِ﴾⟪3:59⟫. في حكمه، وأن ذلك لا يشق عليه كما\nلم يشق عليه أن خلق آدم من غير أبوين.\nإن قيل : ما معنى قوله:\n⟦2:601⟧\n(كن) بعد أن خلقه من تراب؟\nقيل: معناه كن إنسانا حيا ناطقا، وهو لم يكن كذلك، بل كان دهرا جسدا ملقى لا روح فيه.\nعلى ما روي في الخبر، ثم جعل فيه الروح، وجعل كن عبارة\n⟦2:602⟧\nعن إيجاد الصورة التي بها صار الإنسان إنسانا، وعلى هذا\nقال: ﴿إِنَّمَا قَوۡلُنَا لِشَيۡءٍ إِذَآ أَرَدۡنَٰهُ أَن نَّقُولَ لَهُۥ كُن فَيَكُونُ﴾⟪16:40⟫\nفالمقول له الجسد، وقد تقدم الكلام في كن.\nإن قيل: لم قال: (فيكون) ولم يقل فكان؟\nقيل: يكون عبارة عن حال كونه، وحكاية الحال هكذا يخرج نحو قولهم: فلان قال أمس كذا فيفعل به كذا.\nإن قيل: لم رفع يكون ولم ينصب على جواب الأمر؟\nقيل: جواب الأمر يجب أن يكون غيره، نحو: ائتني\n⟦2:603⟧\nفأكرمك، وتقديره: ائتني فإنك إن تأتني أكرمك، ولو جعل\nفيكون جوابا لكان، تقديره كن، فإنك إن تكن تكن، وهذا لا\nيصح؛ لأن معنى الجواب معنى الشرط، وإذا رفع فتقديره: فهو يكون."}, {"a": [60], "v": 2, "p": 603, "ev": 2, "ep": 604, "sid": 805, "t": "قوله عز وجل: (الحق من ربك فلا تكن من الممترين (60)\nالامتراء: استخراج الرأي للشك العارض، ويجعل عبارة عن\nالشك، وإنما قال: ﴿فَلَا تَكُن مِّنَ ٱلۡمُمۡتَرِينَ﴾⟪3:60⟫ ولم يقل ممتريا.\nليكون فيه ذم من شك في عيسى.\nوقوله (الحق) خبر مبتدأ محذوف، أو مبتدأ وخبره (من ربك).\nونبه أن الحق في\n⟦2:604⟧\nذلك، بل في الأمور كلها ما يكون مصدره من الله تعالى.\nوقوله: ﴿فَلَا تَكُن مِّنَ ٱلۡمُمۡتَرِينَ﴾⟪3:60⟫ وإن كان خطابا للنبي - صلى الله عليه وسلم - فالمقصد به عام."}, {"a": [61], "v": 2, "p": 604, "ev": 2, "ep": 608, "sid": 806, "t": "قوله عز وجل: (فمن حاجك فيه من بعد ما جاءك من العلم فقل تعالوا ندع أبناءنا وأبناءكم ونساءنا ونساءكم وأنفسنا وأنفسكم ثم نبتهل فنجعل لعنت الله على الكاذبين (61)\nأصل البهل: ترك الشيء غير مراعى، من قولهم بهلت الناقة: تركتها\nبلا صرار.\nواللعن: الطرد، وقد يستعمل البهل بمعنى\n⟦2:605⟧\nاللعن، وقد تقدم أن لعن الله قد يكون بمنع التوفيق عن\nالكافر وتركه وشؤمه، وهذا نهاية الخذلان.\nوتعال: قال أهل اللغة أصله أن يدعو إلى - مكان رفيع.\nثم جعل عاما في الدعاء إلى كل مكان.\nوالأولى أنه دعاء الإنسان إلا ما فيه علو منزلة:\nإما على الحقيقة، وإما على سبيل الفضول، كقولهم:\nهلم إلى السعادة.\nوقوله: ﴿حَآجَّكَ فِيهِ﴾⟪3:61⟫ أي في كون عيسى عند الله كآدم.\nوقيل في قوله: ﴿ٱلۡحَقُّ مِن رَّبِّكَ فَلَا تَكُن مِّنَ ٱلۡمُمۡتَرِينَ﴾⟪3:60⟫.\n⟦2:606⟧\nوكلا القولين واحد في التحقيق، لأن كليهما في\nأمر عيسى، والآية نزلت في نصارى نجران، إذ عارضوا النبي\n- صلى الله عليه وسلم - في أمر عيسى عليه الصلاة والسلام.\nويقال: لما نزلت أخذ النبي - صلى الله عليه وسلم - بيد الحسن والحسين\n⟦2:607⟧\nوعلي وفاطمة. ثم دعا النصارى إلى المباهلة فأحجموا.\nوقال بعضهم لبعض: إن باهلتموه اضطرم الوادي عليكم نارا.\nفلم يبق نصراني ولا نصرانية.\nوقال بعضهم: وفي هذا إشارة إلى\n⟦2:608⟧\nظهور بطلان الدعاوى الكاذبة عند أهل الحقائق."}, {"a": [62], "v": 2, "p": 608, "ev": 2, "ep": 610, "sid": 810, "t": "قوله عز وجل: (إن هذا لهو القصص الحق وما من إله إلا الله وإن الله لهو العزيز الحكيم (62)\nأي أن ما قص الله عليكم من أمر عيسى هو الحق، وأن المستحق لعبادته هو الله، لا إله غيره، وأن لا عزة ولا عز ولا حكم ولا حكمة إلا له تعالى في الحقيقة، فهو الذي لا تلحقه ذلة ولا تعتريه جهالة، وكل من حصل له شيء\nمن العز والحكم فمنه مستفاد.\nوالقصص: كل خبر مقتطع\n⟦2:609⟧\nعلى وجهته من قولهم: قصصت أثره، وقصصت الظفر.\nوهو اسم للمقصوص: كالقبض والنقص، للمقبوض والمنقوص.\nوظاهر قوله: ﴿وَمَا مِنۡ إِلَٰهٍ إِلَّا ٱللَّهُۚ﴾⟪3:62⟫ أبلغ من قولنا:\nوما إله، لاستغراقه، ولا يصح جر لفظ الله على البدل من إله، لأن من\nهذه لا تدخل إلا على كل نكرة غير موجبة، فإذن لا يكون إلا\nرفعا ردا على موضع (من إله)، وأعاد ذكر الله ظاهرا على\n⟦2:610⟧\nطريق التعظيم، وخص (العزيز) تنبيها أنه تعالى مستغن عن\nالتكثر بالولد على ما تقدم، وفيه تنبيه أنه أظهر عزته عما ينسب\nإليه من الولد بما قدمه من الحجة، وأنه حكيم لا يفعل ما ينافي\nحكمته، واتخاذ الولد مما ينافي حكمته."}, {"a": [63], "v": 2, "p": 610, "ev": 2, "ep": 610, "sid": 812, "t": "قوله عز وجل: (فإن تولوا فإن الله عليم بالمفسدين (63)\nأي إن أعرضوا عن الإصغاء إلى الحق والتزامه، وعن الإجابة إلى\nالمباهلة، فإن حالهم في كونهم مفسدين ظاهرة، وعقوبتهم\nواجبة، فهو تعالى معاقبهم."}, {"a": [64], "v": 2, "p": 610, "ev": 2, "ep": 617, "sid": 812, "t": "قوله تعالى: (قل يا أهل الكتاب تعالوا إلى كلمة سواء بيننا وبينكم ألا نعبد إلا الله ولا نشرك به شيئا ولا يتخذ بعضنا بعضا أربابا من دون الله فإن تولوا فقولوا اشهدوا بأنا مسلمون (64)\nقال محمد بن جعفر والحسن والسدي: عنى بأهل الكتاب هاهنا\n⟦2:611⟧\nنصارى نجران، وقال قتادة والربيع: عنى يهود المدينة.\nوقيل: عنى الفريقين، لقوله في ذمهما: ﴿ٱتَّخَذُوٓاْ أَحۡبَارَهُمۡ وَرُهۡبَٰنَهُمۡ أَرۡبَابٗا مِّن دُونِ ٱللَّهِ﴾⟪9:31⟫\n⟦2:612⟧\nو (سواء) وسوى: وسط، ويعني به العدل.\nوقول الربيع وأبي العالية (كلمة سواء)\nهي لا إله إلا الله، فصحيح، لأن أبلغ العدالة التوحيد، وهي\n⟦2:613⟧\nالكلمة التي يجب أن يتساوى الناس فيها، وفي أن يكونوا\nعابدين غير معبودين، بخلاف ما ادعته النصارى، ونبه بقوله:\nلا نشرك أن قولهم يقتضى الشرك، وإن كانوا منكرين أنهم\nمشركون، وموضع (ألا نعبد) خفض بدل من كلمة، أو رفع\nعلى أنه خبر ابتداء مضمر، كأنه قيل: وهي ألا نعبد، ولو\nرفع سواء، نحو قوله ﴿سَوَآءٗ مَّحۡيَاهُمۡ وَمَمَاتُهُمۡۚ﴾⟪45:21⟫ جاز\n⟦2:614⟧\nوكذلك يجوز رفع (ألا نعبد) على معنى: أنه لا نعبد.\nوقال بعض الصوفية: نبهنا الله تعالى بهذه الآية على طريق\nالتعبد، وأن لا نقصد بسرنا سواه عند عبادته، ولا نفزع في شيء\nمن الحاجات إلى غيره، فنكون كمن وصفه النبي - صلى الله عليه وسلم - \"تعس عبد الدينار، تعس عبد الدرهم \".\nإن قيل: فأي حجة في قوله: ﴿فَإِن تَوَلَّوۡاْ فَقُولُواْ ٱشۡهَدُواْ﴾⟪3:64⟫ قيل: إنه تعالى أدبنا بأن المعاند متى لزمته الحجة وبانت له المحجة فليس إلا التقضي منه وترك\n⟦2:615⟧\nمحجته وملاحاته.\nإن قيل: كيف قال: ﴿وَلَا نُشۡرِكَ بِهِۦ شَيۡـٔٗا وَلَا يَتَّخِذَ بَعۡضُنَا بَعۡضًا أَرۡبَابٗا مِّن دُونِ ٱللَّهِۚ﴾⟪3:64⟫ وكلاهما أفاد ما أفاد قوله ﴿أَلَّا نَعۡبُدَ إِلَّا ٱللَّهَ﴾⟪3:64⟫؟\nقيل: ليس كذلك، فإن الشرك بالله قد يكون في غير العبادة.\nألا ترى أن النبي - صلى الله عليه وسلم - قال:\n⟦2:616⟧\n\"الشرك أخفى فيكم من دبيب النمل على الصفا في الليلة الظلماء\".\nمن ذلك قول القائل: لولا الديك لأتانا اللص.\nوقال تعالى: ﴿وَمَا يُؤۡمِنُ أَكۡثَرُهُم بِٱللَّهِ إِلَّا وَهُم مُّشۡرِكُونَ﴾⟪12:106⟫.\nوقوله: ﴿وَلَا يَتَّخِذَ بَعۡضُنَا بَعۡضًا أَرۡبَابٗا مِّن دُونِ ٱللَّهِۚ﴾⟪3:64⟫.\nفقد شرط من دون الله\n⟦2:617⟧\nوهنا هو الكفر، فأما المملوك إذا اتخذ صاحبه ربا لا أنه معبود\nفليس بمنهي عنه."}, {"a": [65], "v": 2, "p": 617, "ev": 2, "ep": 620, "sid": 819, "t": "قوله عز وجل: (يا أهل الكتاب لم تحاجون في إبراهيم وما أنزلت التوراة والإنجيل إلا من بعده أفلا تعقلون (65)\nقال ابن عباس والحسن والسدي: اجتمع أحبار اليهود ونصارى\nنجران عند رسول الله - صلى الله عليه وسلم - فتنازعوا في إبراهيم.\nفقالت اليهود: ما كان إلا يهوديا، وقالت النصارى: ما كان إلا نصرانيا، - فأبطل الله دعواهما، وبين أن ذلك محال، لأن المتقدم لا يكون\n⟦2:618⟧\nمنسوبا إلى المتأخر ومقتديا به.\nإن قيل: فإن اليهود والنصارى لم يدعوا أكثر من أن شريعتنا مساوية لشريعة إبراهيم، وهذا قد ادعاه المسلمون، فإن أمكننا أن نلزمهم. ذلك أمكنهم أن يعارضوا بمثله؟\nقيل: إنا لم ندع أن إبراهيم منسوب في الشريعة إلى محمد\n- صلى الله عليه وسلم - كما ادعوه، وإنما قلنا كان حنيفا مسلما، والحنيف المستقيم والمائل إلى الحق، والمسلم المطيع والمستسلم للحق، وهذا\nمن الأسماء التي يتخصص بها كل ذي حق، ولهذا قال:\n⟦2:619⟧\n﴿إِنَّ ٱلدِّينَ عِندَ ٱللَّهِ ٱلۡإِسۡلَٰمُۗ﴾⟪3:19⟫، واليهود منسوب إلى يهودا.\nوالنصارى إلى ناصرة، وهما نسبتان حصلتا بعد إبراهيم.\nفكذبوا في نسبته إليهما، ثم المسلمون موافقون لإبراهيم في كثير\nمن الأحكام: كحج البيت، والختان، والمضمضة وغير ذلك.\nوهم يخالفونه في أكثر ذلك، وأيضا فقد ورد في القرآن أن شريعتنا\n⟦2:620⟧\nموافقة لشريعته فيما حكى، وهذا ظاهر، ونبه بقوله ﴿أَفَلَا تَعۡقِلُونَ﴾⟪3:65⟫\nأن ما يقولونه ويفعلونه بخلاف مقتضى العقل.\nوأن العقل يزجر عن اتباع دعوى بلا حجة."}, {"a": [66], "v": 2, "p": 620, "ev": 2, "ep": 621, "sid": 822, "t": "قوله عز وجل: (ها أنتم هؤلاء حاججتم فيما لكم به علم فلم تحاجون فيما ليس لكم به علم والله يعلم وأنتم لا تعلمون (66)\nها للتنبيه عما يضل عنه الإنسان أو يغفل، تقول ها أنا ذا. تنبيها\nلمن غفل عنك.\nفإن قيل: فهب أن الإنسان يغفل عن غيره، فكيف يغفل عن نفسمه، حتى يقال: ها أنتم؟\nقيل: فليس حقيقة (ها أنتم) تنبيه المخاطب على وجود ذاته، وإنما هو تنبيه على أحواله التي غفل عنها، فالإنسان قد يغفل عن كثير من معايبه\nلشغفه بنفسه، فيحتاج أن ينبه عليه، ولهذا لا يقتصر علي قوله:\n⟦2:621⟧\n(ها أنتم) حتى يضم إليه حالة ما، مما غفلوا عنه، وفي الآية تنبيه\nعلى حالة غفلوا عنها، وهي أنهم حاجوا فيما لا علم لهم به.\nولم ترد به التوراة والإنجيل، فيقول: هب أنكم تحتجون فيما ورد به كتب\nالله المتقدمة فلم تحتجون فيما ليس كذلك؟ ونبه أن المحاجة\nإعلام الحجة، ومن لا يعرفها فكيف يعرفها؟\nوفي قوله ﴿وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ﴾⟪3:66⟫\nاستدعاء لأن يسمعوا، كقولك لمن أخبرته بشيء لا يعلمه:\nاسمع فإني أعلم ما لا تعلم، و (هؤلاء)\nهاهنا جار مجرى الذين و (حاججتم) صلته.\nوقيل: بل هو تابع لأنتم جار مجرى عطف البيان، و (حاججتم) هو\nالخبر، والمعنى لا يتغير باختلاف التقديرين."}, {"a": [67], "v": 2, "p": 621, "ev": 2, "ep": 622, "sid": 823, "t": "قوله عز وجل: (ما كان إبراهيم يهوديا ولا نصرانيا ولكن كان حنيفا مسلما وما كان من المشركين (67)\nأنكر الله عليهم محاجتهم في\n⟦2:622⟧\nإبراهيم، واستجهلهم فيما ادعوه، وأنه كان على إحدى الملتين\nاليهودية والنصرانية، وبت الحكم على كونه حنيفا مسلما على ما\nتقدم، ثم بين أنه لم يكن من المشركين؛ تنبيها أن اليهود\nوالنصارى فيما ابتدعوه وادعوه مشركون .."}, {"a": [68], "v": 2, "p": 622, "ev": 2, "ep": 624, "sid": 824, "t": "قوله عز وجل (إن أولى الناس بإبراهيم للذين اتبعوه وهذا النبي والذين آمنوا والله ولي المؤمنين (68)\nقد تقدم معنى الولاية والاتباع، وأنه تارة يكون بالسنن\nوتارة يكون بالاعتقاد.\nوهذا الثاني هو المراد، ومعنى الآية أن أصدق الناس موالاة لإبراهيم\nمن تبعه في اعتقاده وأفعاله، وهذا النبي والذين آمنوا هم المتبعون\nله، فإذن هم أحق به، فعلى قوله: ﴿وَهَٰذَا ٱلنَّبِيُّ وَٱلَّذِينَ ءَامَنُواْۗ﴾⟪3:68⟫\n⟦2:623⟧\nمبتدأ محذوف الخبر، وقيل: عنى بقوله الذين اتبعوه:\nالمتبعون له في زمانه، وقوله: ﴿وَهَٰذَا ٱلنَّبِيُّ﴾⟪3:68⟫ معطوف عليه.\nإن قيل: لم أفرد ذكر النبي - صلى الله عليه وسلم - عن المؤمنين؟\nقيل: لأنه هو المقصود بالولاية، والمؤمنون غير الذين آمنوا وهم تابعوه، ويجوز أن يجعل المؤمنون عاما، ويكون إفراد النبي - صلى الله عليه وسلم - تعظيما له كإفراد جبريل وميكائيل عن الملائكة، وقدم ذكره تشريفا له، كقوله:\n⟦2:624⟧\n﴿وَمَآ أُوتِيَ مُوسَىٰ وَعِيسَىٰ وَٱلنَّبِيُّونَ﴾⟪3:84⟫ فقدم ذكرهما، وإن كانا\nمن جملة النبيين، وإنما قال: ﴿وَٱللَّهُ وَلِيُّ ٱلۡمُؤۡمِنِينَ﴾⟪3:68⟫ ولم يقل: وليهم.\nتنبيها أن موالاة الله تعالى تستحق بالإيمان، وأنها ليست بمقصورة\nعلى من تقدم ذكرهم، بل ذلك لكل مؤمن في كل وقت.\nوالولي هاهنا يحتمل على وجهين:\nأحدهما: أن يكون بمعنى الفاعل.\nولما ذكر حال إبراهيم ومشاحة الناس في الانتساب إليه نبه\nبقوله: ﴿وَٱللَّهُ وَلِيُّ ٱلۡمُؤۡمِنِينَ﴾⟪3:68⟫ أن إبراهيم استحق منزلته.\nوالثاني: أن يكون بمعنى الموالى، أي المؤمنون هم الذين يوالون الله.\nفأما الكفار فيوالون الشيطان، كما قال تعالى: ﴿وَٱلَّذِينَ كَفَرُوٓاْ أَوۡلِيَآؤُهُمُ ٱلطَّٰغُوتُ﴾⟪2:257⟫."}, {"a": [69], "v": 2, "p": 625, "ev": 2, "ep": 629, "sid": 827, "t": "قوله عز وجل: (ودت طائفة من أهل الكتاب لو يضلونكم وما يضلون إلا أنفسهم وما يشعرون (69)\nالطائفة: جمع طائف وهو الذي يطوف، وذلك اعتبارا بطوافهم بالبيت وغيره من متعبداتهم، ولطوافهم في أسفارهم، ثم سمي كل جمع طائفة.\nطافوا أو لم يطوفوا، كتسميتهم بالرفقة، ترافقوا أو لم يترافقوا.\nوالإضلال: فعل ما يحصل عنده الضلال، ويقال ذلك له لقصد\nالفاعل ذلك أولا، لأنه يقال مفازة مضلة، كما يقال: أضلني\nفضللت، ويقال: أضله، سواء فعل ذلك بدعا أو بغيره، كما\nيقال: أضله الشيطان، قال تعالى حكاية عنه:\n⟦2:626⟧\n﴿وَمَا كَانَ لِيَ عَلَيۡكُم مِّن سُلۡطَٰنٍ إِلَّآ أَن دَعَوۡتُكُمۡ فَٱسۡتَجَبۡتُمۡ لِيۖ﴾⟪14:22⟫\nلكن الإضلال متى كان معه الضلال لا يصح أن ينفى، فيقال:\nما أضل المؤمن، ويقال تارة الشيطان، وإذا لم يكن معه الضلال صح النفي فيه والإثبات جميعا، ويقال تارة: الشيطان أضل المؤمن ولم يضل.\nوالود ضرب من المحبة، ويستعمل في معنى التمني، فمتى\nقصد به التمني استعمل معه: أن، وتارة: لو، يقول: وددت\n⟦2:627⟧\nلو خرجت، ولا يجوز إدخال لو فيه إذا أريد معه المحبة.\nوإذا كان بمعنى المحبة يتعلق بالأزمنة الثلاثة، وإذا كان للتمني\nفليس إلا للاستقبال. بين تعالى أن طائفة من اليهود والنصارى\nيتمنون أن يفعلوا ما يؤدي المسلمين إلى ضلالهم وهلاكهم، وكل\nما يفعلونه يؤديهم إلى هلاك أنفسهم، ثم بين أنهم لا يشعرون\n⟦2:628⟧\nأنهم يضلون أنفسهم، وإنما قال: ﴿لَّا يَشۡعُرُونَ﴾ مبالغة في\nذمهم، وأنهم افتقدوا المنفعة بحواسهم، كقوله تعالى: ﴿صُمُّۢ بُكۡمٌ عُمۡيٞ﴾ وقول من قال: الآية تدل على أن المعارف مكتسبة\nبقوله: ﴿وَمَا يَشۡعُرُونَ﴾⟪3:69⟫، فبعيد عن تصور الفرق بين قولهم:\nيشعر ويعلم، وروي في سبب نزول هذه الآية: أن قوما من\nاليهود دعوا عمار بن ياسر\n⟦2:629⟧\nوحذيفة بن اليمان إلى اليهودية."}, {"a": [70], "v": 2, "p": 629, "ev": 2, "ep": 630, "sid": 831, "t": "قوله عز وجل: (يا أهل الكتاب لم تكفرون بآيات الله وأنتم تشهدون (70)\nالشهادة: الإخبار بالشيء عن مشاهدة: إما ببصر.\nأو ببصيرة، ثم يعبر بها عن المعرفة القتضية لصحة ما يدعي، وإن\nكان المدعى عليه منكرا بلسانه كقولك لخصمك: أنت تشهد أن\nالأمر بخلاف ما تذكره.\nفقوله: ﴿لِمَ تَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ﴾⟪3:70⟫\nمنهم من خص، فقال: عنى بذلك الآيات المنزلة على محمد - صلى الله عليه وسلم -\n⟦2:630⟧\nومنهم من قال: عنى الآيات التي تدل من الكتابين على صحة\nنبوة محمد - صلى الله عليه وسلم -\n(وأنتم تشهدون) يعني شهادة بالقلب دون اللسان، أو عنى ما يكون من شهادتهم ﴿يَوۡمَ تَشۡهَدُ عَلَيۡهِمۡ أَلۡسِنَتُهُمۡ وَأَيۡدِيهِمۡ وَأَرۡجُلُهُم﴾⟪24:24⟫.\nوقيل: معناه: وأنتم تشهدون يا أهل الكتاب: لم تلبسون الحق بالباطل، تنبيها أنهم يفعلون ذلك حماية على رياستهم وعصبية لملتهم، لا جهلا بالحق، بل هم يعلمون."}, {"a": [71], "v": 2, "p": 631, "ev": 2, "ep": 634, "sid": 833, "t": "قوله عز وجل: (يا أهل الكتاب لم تلبسون الحق بالباطل وتكتمون الحق وأنتم تعلمون (71).\nلبس الحق بالبطل على ثلاثة أوجه:\nالأول: أن يحرف الحق، فيجعل في صورة الباطل.\nوالثاني: أن يزين الباطل، فيجعل في صورة الحق.\nالثالث: أن لا يميز أحدهما عن الآخر مع الإمكان.\nوقد فسرت الآية على الأوجه الثلاثة.\nقال الحسن وابن زيد: هو تحريف التوراة والإنجيل،\n⟦2:632⟧\nوقال بعضهم: هو الكفر بمحمد - صلى الله عليه وسلم - مع المعرفة بصدقه، وقيل: هو ما ذكره تعالى من بعد في قول بعضهم لبعض ﴿ءَامِنُواْ بِٱلَّذِيٓ أُنزِلَ عَلَى ٱلَّذِينَ ءَامَنُواْ وَجۡهَ ٱلنَّهَارِ﴾⟪3:72⟫.\nوأما كتمانهم الحق فما كتموه من صفات النبي - صلى الله عليه وسلم - التي دل عليها إشارات التوراة والإنجيل، وقد نهى النبي - صلى الله عليه وسلم - عن كتمان العلم بقوله:\n⟦2:633⟧\n\"من سئل عن علم فكتمه. . . \" الخبر، وعنى بالآية كتمانه مع\nوجوب إظهاره:\nفأما صيانة الحكمة عمن لا يستحقها؛ إما لقصوره عن الوقوف عليها، أو خوفا أن يجعلها ذريعة إلى فساد، فذلك واجب.\nوقوله: ﴿وَأَنتُمۡ تَعۡلَمُونَ﴾⟪3:71⟫ أي تعرفون الحق\n⟦2:634⟧\nالذي تكتمونه، والتلبيس الذي تاتونه.\nإن قيل: لم قال هاهنا: (وأنتم تعلمون)، وقال فيما قبله:\n﴿وَأَنتُمۡ لَا تَعۡلَمُونَ﴾؟\nقيل: الذي نفى عنهم ما ادعوه من كون إبراهيم يهوديا أو نصرانيا.\nوليس ذلك في كتابهم.\nوما أثبت لهم هاهنا وقفوا عليه من كتابهم من أمر النبي - صلى الله عليه وسلم - فجحدوه، وهذا غاية الذم، إذ جحدوا ما علموا، وادعوا ما جهلوا."}, {"a": [72], "v": 2, "p": 635, "ev": 2, "ep": 638, "sid": 837, "t": "قوله عز وجل: (وقالت طائفة من أهل الكتاب آمنوا بالذي أنزل على الذين آمنوا وجه النهار واكفروا آخره لعلهم يرجعون (72)\nالوجه: أصله الجارحة، ولما كان هو أول ما يستقبلك، وأشرف\nما في البدن، تارة يستعمل في أشرف الشيء، فيقال: هذا وجه\nكذا، وتارة في مبدئه، نحو: وجه النهار.\nوقوله: (آمنوا) أي أظهروا الإيمان، وقوله: ﴿ٱلَّذِينَ ءَامَنُواْ﴾⟪3:72⟫ أي آمنوا بمحمد - صلى الله عليه وسلم -.\nوالطائفة التي قالت ذلك قال قتادة والربيع: هم اليهود بعضهم لبعض،\n⟦2:636⟧\nوقال الحسن: يهود خيبر، قالوا: ليهود المدينة فخصص.\nومعنى الآية قيل: إن النبي - صلى الله عليه وسلم - صلى صلاة الفجر إلى بيت المقدس، ثم نسخ الله ذلك في آخر النهار، فقال: آمنوا بصلاتهم وجه النهار إلى بيت المقدس، واكفروا بصلاتهم في آخر النهار إلى الكعبة، لعلهم يتركون إذا رأوا التواءكم عليهم، وعبر عما فعله المسلمون بالإنزال إليهم.\nلا أنهم أقروا بأن ذلك منزل، ولكن على حسب ما قاله المسلمون\nواعتقدوه.\nوقيل: ليس القصد في الحقيقة إلى صدر النهار وآخره.\nبل لما عجزوا عن صرف المؤمنين عن موافقة النبي - صلى الله عليه وسلم - مكاشفة، قالوا: إذا مروهم بأن يساعدوهم مرة ويخالفوهم مرة؛ ليحتالوا\nعلى صرفهم عن اتباعه بذلك، فحذر الله المؤمنين منهم\n⟦2:637⟧\nليحترزوا. ومنهم من حمل وجه النهار وآخره على مجاز\nآخر، فقال: معناه آمنوا في الظاهر، واكفروا به في الحقيقة.\nوذلك هو المعبر عنه بقوله: ﴿وَإِذَا لَقُواْ ٱلَّذِينَ ءَامَنُواْ﴾ الآية.\nوقيل: فيه وجه رابع، وهو أن علماء اليهود وكانوا قد حدثوا\nقبل بعثة النبي - صلى الله عليه وسلم - بأخبار له وجدت على ما أخبروا به، ثم لما رأوا رياستهم تبطل به ندموا، فقال بعضهم لبعض: قد أخبرنا اليهود\nبما أخبرنا، فإن كذبناه دفعة اتهمونا، ولكن نؤمن ببعض، ونكفر\n⟦2:638⟧\nببعض، أي نوهمهم أولا أنا نظنه صادقا ثم يكذبونه، فهذا\nمعنى ﴿ءَامَنُواْ وَجۡهَ ٱلنَّهَارِ وَٱكۡفُرُوٓاْ ءَاخِرَهُۥ﴾⟪3:72⟫.\nولإظهارهم الإيمان طورا والكفر طورا، قال تعالى: ﴿إِنَّ ٱلَّذِينَ ءَامَنُواْ ثُمَّ كَفَرُواْ ثُمَّ ءَامَنُواْ ثُمَّ كَفَرُواْ ثُمَّ ٱزۡدَادُواْ كُفۡرٗا﴾⟪4:137⟫ الآية."}, {"a": [73], "v": 2, "p": 638, "ev": 2, "ep": 648, "sid": 840, "t": "قوله تعالى: (ولا تؤمنوا إلا لمن تبع دينكم قل إن الهدى هدى الله أن يؤتى أحد مثل ما أوتيتم أو يحاجوكم عند ربكم قل إن الفضل بيد الله يؤتيه من يشاء والله واسع عليم (73)\nفي قوله ﴿أَن يُؤۡتَىٰٓ أَحَدٞ﴾⟪3:73⟫\nقولان: أحدهما: أن يتصل بقو له: (ولا تؤمنو).\n⟦2:639⟧\nوالثاني: أن يتصل بقوله: ﴿قُلۡ إِنَّ ٱلۡهُدَىٰ﴾⟪3:73⟫ فإذا جعلته متصلا بقوله:\n﴿وَلَا تُؤۡمِنُوٓاْ﴾⟪3:73⟫ فتقديره: ولا تؤمنوا بأن يؤتى أحد، لكن حذف\nالجار لكثرة حذفه مع أن.\nإن قيل: كيف يصح أن يكون (تؤمنوا) مفعوله (أن يؤتى) وقد عدي إلى قوله: ﴿لِمَن تَبِعَ دِينَكُمۡ﴾⟪3:73⟫ و (ءامن) لا يصح أن يعدى إلى مفعولين بغير حرف\nالعطف؟\n⟦2:640⟧\nقيل: إن اللام تتعلق به، لا على حد المفعول به، وتقدير\nالكلام: لا تقروا بأن يؤتى أحد مثل ما أوتيتم إلا لمن تبع.\nوقول من قال: اللام زائدة نحو ﴿رَدِفَ لَكُم﴾⟪27:72⟫ فبعيد، لأن\nآمن هنا لا يتعدى إلا بالجار.\nوفي قوله: ﴿أَن يُؤۡتَىٰٓ أَحَدٞ مِّثۡلَ مَآ أُوتِيتُمۡ﴾⟪3:73⟫ على هذا\n⟦2:641⟧\nقولان: أحدهما: لا تقروا أن أحدا عرف محمدا كما قد عرفتموه.\nوالثاني: أن خص أحد من العلوم والكراما) بمثل ما خصصتم .\nوقوله ﴿أَوۡ يُحَآجُّوكُمۡ﴾⟪3:73⟫ أي أو أن يجعل الله للمسلمين حجة يحاجونكم\nبها عند الله، فأكذبهم الله تعالى في الأمرين جميعا ورد عليهم.\nأما في الأول فبقوله: ﴿قُلۡ إِنَّ ٱلۡهُدَىٰ هُدَى ٱللَّهِ﴾⟪3:73⟫ تنبيها أن ذلك\nيعطيه من يشاء، نحو ﴿وَٱللَّهُ يَهۡدِي مَن يَشَآءُ﴾.\nأما في الثاني، وهو قوله: ﴿أَوۡ يُحَآجُّوكُمۡ﴾⟪3:73⟫ فبقوله: ﴿قُلۡ إِنَّ ٱلۡفَضۡلَ بِيَدِ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۗ﴾⟪3:73⟫.\nفقوله: ﴿قُلۡ إِنَّ ٱلۡهُدَىٰ﴾⟪3:73⟫ اعتراض بين بعض الجملة وبعضها.\nتسديدا لها وجوابا لهم، وكذلك قوله: ﴿قُلۡ إِنَّ ٱلۡفَضۡلَ بِيَدِ ٱللَّهِ﴾⟪3:73⟫\n⟦2:642⟧\nجواب لهم.\nوالاعتراض بين المتصلين من الجملة بما فيه تحقيق\nلمقتضاها، أو رد لها من بلاغات كلامهم، وعلى ذلك قوله:\n﴿إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ إِنَّا لَا نُضِيعُ أَجۡرَ مَنۡ أَحۡسَنَ عَمَلًا ۝ أُوْلَٰٓئِكَ﴾⟪18:30-31⟫ فقوله: ﴿إِنَّا لَا نُضِيعُ أَجۡرَ مَنۡ أَحۡسَنَ عَمَلًا﴾⟪18:30⟫ فصل بين اسم إن وخبره، لتحقيق مقتضى الكلام.\nوالثاني: وهو أن يجعل أن متصلا بقوله: ﴿قُلۡ إِنَّ ٱلۡهُدَىٰ هُدَى ٱللَّهِ﴾⟪3:73⟫، ويكون كلام اليهود قد انقطع عند قوله: ﴿وَلَا تُؤۡمِنُوٓاْ إِلَّا لِمَن تَبِعَ دِينَكُمۡ﴾⟪3:73⟫.\n⟦2:643⟧\nوفيه أوجه، الأول: ما قاله الكسائي والفراء\nوهو: أن أن هاهنا تقتضي معنى لا، كما تقتضيه في قوله: ﴿يُبَيِّنُ ٱللَّهُ لَكُمۡ أَن تَضِلُّواْۗ﴾⟪4:176⟫ ومعناه: البيان بيان الله، وقد بين أن لا يخص أحد من الأمم بمثل ماخصصتم به أيها المؤمنون،\n⟦2:644⟧\nإذ دين الإسلام أكمل الأديان، ومصون عن الإفراط والتفريط.\nوقد تقدم أن شريعة الله قبل نبينا عليه الصلاة والسلام كانت في\nحكم النشوء والتكميل، وبه عليه الصلاة والسلام كملت.\nولهذا قال. ﴿ٱلۡيَوۡمَ أَكۡمَلۡتُ لَكُمۡ دِينَكُمۡ﴾⟪5:3⟫\nوقال: ﴿وَكَذَٰلِكَ جَعَلۡنَٰكُمۡ أُمَّةٗ وَسَطٗا﴾⟪2:143⟫\nويقوي أن معنى (أن يؤتى) لا يؤتى قول الحسن: إن معناه: فلن يؤتى أحد مثل ما أوتيتم أيها المؤمنون.\nقال المبرد: لا يكون أن في كلامهم مقتضيا ل \"لا\"، وإنما تقدير\n⟦2:645⟧\nذلك: كراهة أن يؤتى أحد، وجعل المعنى بهما تقدم، وهذا\nالتقدير بعيد، لأجل أن أحدا هذا يختص بالنفي وما في معناه.\nوعلى تقديره، ويكون مستعملا في الإيجاب. على أن بعض\nالنحويين ذكروا أن أحدا هاهنا هو المستعمل في الإثبات في نحو\nقوله: ﴿قُلۡ هُوَ ٱللَّهُ أَحَدٌ﴾⟪112:1⟫.\nوقوله: ﴿أَوۡ يُحَآجُّوكُمۡ﴾⟪3:73⟫ تقديره عند الفراء: حتى يحاجوكم أو إلي أن يحاجوكم، وذلك على سبيل التبعيد.\nوعلى قول الكسائي: معطوف على قوله ﴿أَن يُؤۡتَىٰٓ﴾⟪3:73⟫\nعلى تقدير أو أن يحاجوكم.\nوحكي أنه في قراءة عبد الله: (أن)،\n⟦2:646⟧\nوذكر بعضهم أن قوله: ﴿أَن يُؤۡتَىٰٓ﴾⟪3:73⟫ متعلق بفعل مضمر، وتقدير\nالكلام: قل إن الهدى هدى الله، فلا تجحدوا أن يؤتى أحد مثل\nما أوتيتم، أو أن يحاجوكم، فإن الله عنده الفضل يؤتيه من يشاء.\nفهذه ثلاثة أوجه في قوله: ﴿أَن يُؤۡتَىٰٓ﴾⟪3:73⟫ إذا لم يجعل متعلقا بما\nتقدم، وذكر بعض المفسرين أن قوله: ﴿وَلَا تُؤۡمِنُوٓاْ﴾⟪3:73⟫ كله\nخطاب الله المؤمنين، لا حكاية عن الكفار، وذكر في تفسيره\n⟦2:647⟧\nأوجها: الأول: أن يكون تقديره: ولا تؤمنوا إلا لمن تبع دينكم\nأن يؤتى. ويكون ذلك تبيينا أن هذه الشريعة أكمل الشرائع على\nما تقدم.\nوالثاتي: أن يكون ذلك حثا على موالاة المؤمنين، ونهيا\nعن مخالطة الكافرين، نحو: ﴿وَلَا تَرۡكَنُوٓاْ إِلَى ٱلَّذِينَ ظَلَمُواْ﴾⟪11:113⟫ أو\nنحوها من الآيات.\nوالثالث: أن يكون فيه مع المعنى المتقدم\nحث على أن لا يصاحب المؤمن من لا تكون طريقته طريقته.\nفيشغل عما هو بصدده، وقال بعض الصوفية: لا تفشو أسرار\n⟦2:648⟧\nالحق إلى غير أهله، ولا تصدقوا بظهور كرامة على غير المحافظين\nعلى ظاهر الشريعة، إبطالا لمن يدعي الوصول إليه بلا مشقة\nيتحملها وعبادة يتكلفها، وفي قوله: ﴿وَٱللَّهُ وَٰسِعٌ عَلِيمٞ﴾⟪3:73⟫ تنبيه\nعلى سعة غناه وجوده وعلمه بما يأتيه ويدعه، فلا يتهم فيما\nيفعله ويذره."}, {"a": [74], "v": 2, "p": 648, "ev": 2, "ep": 651, "sid": 850, "t": "قوله عز وجل: (يختص برحمته من يشاء والله ذو الفضل العظيم (74)\nالاختصاص: انفراد بعض الشيء بما لا يشاركه فيه الجملة.\nوالفضل في الإعطاء: الزيادة على المستحق الذي هو العدل،\n⟦2:649⟧\nوهو المعبر عنه با لإحسان في قوله: ﴿إِنَّ ٱللَّهَ يَأۡمُرُ بِٱلۡعَدۡلِ وَٱلۡإِحۡسَٰنِ﴾⟪16:90⟫\nولأنه من تمام قوله: ﴿وَٱللَّهُ وَٰسِعٌ عَلِيمٞ﴾⟪3:73⟫ تنبيها أنه\nإذا كان واسعا وعالما، فسعته تقتضي أن يوسع على عباده.\nوعلمه يقتضي أن لا يحرم رحمته مستحقها، وفضله يقتضي أن\nيتجاوز تحري العدالة إلى تحري الإفضال، وهو أن يفضل على\nغير مستحقيه، وإلا لم يكن فضل عظيم.\nوقول الحسن ومجاهد والربيع: إن الرحمة هاهنا النبوة.\nوقول ابن جريج: هي\n⟦2:650⟧\nالقرآن صحيحان. لأن كليهما داخلان في الرحمة، ولا شك\nأن من أعطيهما فقد خص برحمة منه، وكذلك قول من قال:\nعنى بالرحمة الحسنى المذكورة في قوله: ﴿إِنَّ ٱلَّذِينَ سَبَقَتۡ لَهُم مِّنَّا ٱلۡحُسۡنَىٰٓ﴾⟪21:101⟫ وقول من قال: عنى به الوقوف على حقائق كلامه، الذي خص به خواص عباده الموصوفين بقوله: ﴿وَتَعِيَهَآ أُذُنٞ وَٰعِيَةٞ﴾⟪69:12⟫، فكل ذلك داخل في عموم رحمته.\n⟦2:651⟧\nإن قيل: ما فائدة ترك التبيين في نحو قوله: ﴿يَخۡتَصُّ بِرَحۡمَتِهِۦ مَن يَشَآءُۗ﴾⟪3:74⟫، وإبهام القول فيه؟\nقيل: الفائدة في ذلك أن يبقى رجاء الراجي وخوف الخائف الممدح بهما في قوله: ﴿وَيَرۡجُونَ رَحۡمَتَهُۥ وَيَخَافُونَ عَذَابَهُۥٓۚ﴾⟪17:57⟫، وليقطع بذلك ملاحظات\nالمجاهدات، وليبين أن الإنسان وإن بذل غاية الجهد في العبادة.\nفرحمته هي التي تنقذه، كما قال عليه الصلاة والسلام:\n\"لا يدخل الجنة أحد بعمله \"، قيل: ولا أنت يا رسول الله؟ قال:\n\"ولا أنا، إلا أن يتغمدني الله برحمته\"."}, {"a": [75], "v": 2, "p": 652, "ev": 2, "ep": 656, "sid": 854, "t": "قوله عز وجل: (ومن أهل الكتاب من إن تأمنه بقنطار يؤده إليك ومنهم من إن تأمنه بدينار لا يؤده إليك إلا ما دمت عليه قائما ذلك بأنهم قالوا ليس علينا في الأميين سبيل ويقولون على الله الكذب وهم يعلمون (75)\nيقال: دمت تدوم ودمت تدام.\nوقال بعضهم: مت ودمت، وكل يقول: تدوم وتموت،\n⟦2:653⟧\nوقوله (قائما) قال قتادة: (قائما) بالتقاضي والمطالبة.\nوقال السدي: بالاجتماع معه، وقال غيرهما: القائم بالشيء:\nالمواظب على الشيء، المجتهد في حفظه، نحو قوله: ﴿أُمَّةٞ قَآئِمَةٞ﴾⟪3:113⟫\nوذلك يدخل فيه ما تقدم من الأقوال، وقد تقدم\nالكلام في القنطار، ولما ذكر الله تبجح اليهود بأنهم أوتوا ما لم\n⟦2:654⟧\nيؤت أحد، أكذبهم الله فذكر خيانتهم، لكن فضلهم لما كان من\nجملتهم من له أمانة، وقال قائل: عنى بالذين يؤدون الأمانة\nالمسلمين منهم، مثل عبد الله بن سلام وأشكاله، ورد عليه\nبعض الناس، وقال: إن الآية نزلت بعد إسلام عبد الله، وهذا\nالراد يتصور أن أهل لا يطلق على من أسلموا، وليس الأمر كذلك.\nبل حقيقة أهل الكتاب يتناول من لا ينكر صدقا ولا يجحد حقا.\nولا يتناول من بقي بعد بعثة النبي - صلى الله عليه وسلم - على دينه ولم يتبعه إلا مجازا، وقوله: ﴿ذَٰلِكَ بِأَنَّهُمۡ قَالُواْ لَيۡسَ عَلَيۡنَا فِي ٱلۡأُمِّيِّـۧنَ سَبِيلٞ﴾⟪3:75⟫\n⟦2:655⟧\nأي يخونون، ويقولون: لنا إصابة أموال العرب لشركهم، وإلى هذا\nذهب ابن عباس فقد قال له رجل:، إنا نمر بأهل الكتاب\nفنأكل من طعامهم، ونذبح لهم الدجاج، فقال: وتقولون كما\nقال أهل الكتاب: ﴿لَيۡسَ عَلَيۡنَا فِي ٱلۡأُمِّيِّـۧنَ سَبِيلٞ﴾⟪3:75⟫، لا يجوز إلا بطيب\nالنفس).\nقال الحسن وابن جريج: كانت اليهود عاملوا العرب.\nفلما أسلموا امتنعوا من رد أموالهم، وقالوا: لا يحق لكم بعد\nأن دخلتم في الإسلام، وقيل معناه: ليس علينا سبيل لكوننا\nأبناء الله وأحباءه، ومن عدانا عبيد لنا، ومالهم مالنا فلا حرج\n⟦2:656⟧\nعلينا في تناوله، وهذه أقوال متقاربة، وكانوا قد زعموا أن\nذلك دين شرعه الله لهم، فأكذبهم بقوله: ﴿وَيَقُولُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ﴾⟪3:75⟫، وذكر أنهم يعلمون أن الأمر بخلاف ما يقولون تعظيما لكذبهم."}, {"a": [76], "v": 2, "p": 656, "ev": 2, "ep": 658, "sid": 858, "t": "قوله عز وجل: (بلى من أوفى بعهده واتقى فإن الله يحب المتقين (76)\nعهده: يصح أن يقدر مضافا إلى الفاعل، وأن يكون مضافا إلى\nالمفعول، فالإنسان مدعو إلى الوفاء بهما، وقيل: وفي لغة\n⟦2:657⟧\nنجد، وأوفى لغة الحجاز، وقيل: هما كمحمد وأحمد.\nو (بك) قيل: هو إضراب عن الأول، أي بلى عليهم سبيل، فيكون\nوقفا، وقيل: فيه مع الإضراب عن الأول اعتماد على الثاني.\nنحو أن يقال: قدم فلان. فتقول بلى طلب كذا فلا يوقف عليه.\n⟦2:658⟧\nإن قيل: ما وجه قوله: (واتقى) بعد قوله: ﴿مَنۡ أَوۡفَىٰ بِعَهۡدِهِۦ﴾⟪3:76⟫؟\nقيل: فيه وجهان: أحدهما: أي يجعل التقوى عاما، وإذا جعلت\nالتقوى خاصا فلأنها هي المقصودة.\nإن قيل لم: (يحب المتقين)، ولم يقل: يحبهم؟\nقيل: تنبيها أن محبته إياهم لأجل التقوى، فإنك إذا\nقلت: جاءني يزيد الظريف فأكرمته، لم يقتض صريح اللفظ أن\nإكرامك إياه لظرفه، وفي الآية تنبيه على قياس نتيجته أن الله تعالى لا\nيحب اليهود بوجه، وبيانه أن الله يحب المتقين، ومن لا يوف بعهده\nأفليس بمتق، واليهود غير موفين، فإذن لا يحبهم الله."}, {"a": [77], "v": 2, "p": 658, "ev": 2, "ep": 664, "sid": 860, "t": "قوله عز وجل: (إن الذين يشترون بعهد الله وأيمانهم ثمنا قليلا أولئك لا خلاق لهم في الآخرة ولا يكلمهم الله ولا ينظر إليهم يوم القيامة ولا يزكيهم ولهم عذاب أليم (77)\nعهد الله متضمن\nلكل عهد عهد إليهم بما ركبه تعالى في عقولهم، وما عهد إليهم على\nلسان أنبيائهم، ولما أخذه الإنسان على نفسه من أمر التزمه بنذر، أو\nيمين، أو حلف، أو عقد مما لا يلزمه من جهة الشرع بغير التزام،\n⟦2:659⟧\nوقد تقدم في قوله: ﴿لِيَشۡتَرُواْ بِهِۦ ثَمَنٗا قَلِيلٗاۖ﴾⟪2:79⟫ أنه لم يعن\nبه القلة المعتبرة بإضافة بعض الأثمان إلى بعض، بل ذلك باعتبار\nمنافع الدنيا بمنافع الآخرة، فذم الله تعالى من توصل إلى نفع\nعاجل بإضاعة عهد الله، ولكون الوفاء سببا لعامة الصلاح.\nوالغدر سببا لعامة الفساد، عظم الله أمرهما، وأعاد في عدة مواضع\nذكرهما، فقال: ﴿وَأَوۡفُواْ بِٱلۡعَهۡدِۖ إِنَّ ٱلۡعَهۡدَ كَانَ مَسۡـُٔولٗا﴾⟪17:34⟫.\nوقال: ﴿وَٱلۡمُوفُونَ بِعَهۡدِهِمۡ﴾⟪2:177⟫ وقال:\n⟦2:660⟧\n﴿وَٱلَّذِينَ هُمۡ لِأَمَٰنَٰتِهِمۡ وَعَهۡدِهِمۡ رَٰعُونَ﴾\nوقال: ﴿ٱلَّذِينَ يُوفُونَ بِعَهۡدِ ٱللَّهِ وَلَا يَنقُضُونَ ٱلۡمِيثَٰقَ﴾⟪13:20⟫.\nوكدلك عظم أمر الإيمان لذلك، فقال: ﴿وَلَا تَجۡعَلُواْ ٱللَّهَ عُرۡضَةٗ لِّأَيۡمَٰنِكُمۡ﴾⟪2:224⟫، وقال عليه الصلاة والسلام: \"من حلف على يمين فاجرة؛ ليقتطع بها مال امرئ مسلم، لقي الله وهو عليه غضبان \"، وبين تعالى أن من تحرى غدرا آثر به الحياة\n⟦2:661⟧\nالدنيا فذلك بانه لا خلاق له في الآخرة، أي لا معرفة له بها، ولا\nنصيب له فيها، تنبيها على ما قال: ﴿يَعۡلَمُونَ ظَٰهِرٗا مِّنَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَهُمۡ عَنِ ٱلۡأٓخِرَةِ هُمۡ غَٰفِلُونَ﴾⟪30:7⟫.\nوقوله: ﴿وَلَا يُكَلِّمُهُمُ ٱللَّهُ﴾⟪3:77⟫ فمكالمة الله للعبد قسمان:\nمكالمته إياه في الآخرة، وذلك على أضرب:\nالأول: مكالمته إياه من غير واسطة، وذلك كحال\nموسى عليه الصلاة والسلام، حيث وصفه بقوله: ﴿وَكَلَّمَ ٱللَّهُ مُوسَىٰ تَكۡلِيمٗا﴾⟪4:164⟫.\nوالثاني: مكالمته إياه بواسطة بشرية، وذلك لمن وصفهم بقوله:\n﴿فَأَجِرۡهُ حَتَّىٰ يَسۡمَعَ كَلَٰمَ ٱللَّهِ﴾⟪9:6⟫.\nوالناس في سماع كلام الله تعالى على أضرب:\nالأول: من يسمع كلامه ويعقل معناه ويعمل بمقتضاه.\nوهم الذين ذكرهم بقوله: (فبشر عباد (17) الذين يستمعون القول فيتبعون أحسنه أولئك الذين هداهم الله).\nوالثاني: من يسمعه أو يعقله ولا يعمل به، وهم\n⟦2:662⟧\nالذين ذكرهم بقوله: ﴿يَسۡمَعُونَ كَلَٰمَ ٱللَّهِ ثُمَّ يُحَرِّفُونَهُۥ مِنۢ بَعۡدِ مَا عَقَلُوهُ﴾⟪2:75⟫. والثالث: من يسمعه ولا يعقله ولا يعمل به، الذين ذكرهم بقوله:\n﴿يَسۡمَعُ ءَايَٰتِ ٱللَّهِ تُتۡلَىٰ عَلَيۡهِ ثُمَّ يُصِرُّ مُسۡتَكۡبِرٗا كَأَن لَّمۡ يَسۡمَعۡهَاۖ﴾⟪45:8⟫.\nوأكثر المفسرين حملوا قوله: ﴿وَلَا يُكَلِّمُهُمُ ٱللَّهُ﴾⟪3:77⟫\nعلى الآخرة، فقال بعضهم: عنى أنه لا يكلمهم كلاما يسرهم.\nوأما ما يسوؤهم فبلى، فقد قال: (فوربك لنسألنهم أجمعين (92) عما كانوا يعملون)، وقال بعضهم: لا يكلم الكفار بوجه.\nوإنما يسائلهم بلسان الملائكة،\n⟦2:663⟧\nوقال بعض المفسرين: يتناول ذلك في الدنيا والآخرة، فإنه\nتعالى يكلم أولياءه في الدنيا لانتفاعهم بما يسمعونه من كتابه\nوسائر آياته وآثار صنائعه، ومن لم ينتفعوا بعظاته لم يحصل منه\nلهم مكالمة، ولهذا قال: ﴿وَمَثَلُ ٱلَّذِينَ كَفَرُواْ كَمَثَلِ ٱلَّذِي يَنۡعِقُ بِمَا لَا يَسۡمَعُ إِلَّا دُعَآءٗ وَنِدَآءٗۚ﴾⟪2:171⟫\nوقوله: ﴿وَلَا يَنظُرُ إِلَيۡهِمۡ﴾⟪3:77⟫ فنظر الله إلى العبد يكون في الدنيا\nبإفاضة النعمة، وفي الآخرة بالإثابة،\n⟦2:664⟧\nولما كانت نعمة الله الدنيوية عامة للمسلم والكافر، أو نعمته\nالأخروية محرمة على الكافر، قال: ﴿وَلَا يَنظُرُ إِلَيۡهِمۡ يَوۡمَ ٱلۡقِيَٰمَةِ﴾⟪3:77⟫\nفخص، وأما التزكية فقد تكون في الدنيا بتوفيقه وإرشاده إلى\nما يزداد به العبد بصيرة وفي الآخررة بالإثابة، وكل ذلك ممنوع من\nالكافر، ثم قال: ﴿وَلَهُمۡ عَذَابٌ أَلِيمٞ﴾⟪3:77⟫، تنبيها أن ثمرة منع\nهذه الأشياء إيجاب العذاب لهم، أو تنبيها أنهم مع منعه إياهم\nهذه النعم، يجعل لهم زيادة في العذاب الأليم."}, {"a": [78], "v": 2, "p": 664, "ev": 2, "ep": 667, "sid": 866, "t": "قوله عز وجل: (وإن منهم لفريقا يلوون ألسنتهم بالكتاب لتحسبوه من الكتاب وما هو من الكتاب ويقولون هو من عند الله وما هو من عند الله ويقولون على الله الكذب وهم يعلمون (78)\n⟦2:665⟧\nاللي: من لويت يده، وعنهم لويت الغريم ليا وليانا، فتلته\nعن حقه بمطلة، ولي الألسنة: قيل تحريف اللسان عما في القلب.\nوهو الكذب، وقيل: هو التنطع والتجمل بالكلام لتشبيهه بغيره.\nوقيل: ليهم بألسنتهم: تحريفهم بالتأويل الباطل، وكما ذم\nتعالى بعضهم بقلة الوفاء بعهد الله ذم بعضهم بالكذب على الله\nتعالى، الذي هو أفظع كذب وأشنعه، وعنى بالكتاب الأول ما\nكتبوه بأيديهم المعني بقوله: ﴿فَوَيۡلٞ لِّلَّذِينَ يَكۡتُبُونَ ٱلۡكِتَٰبَ بِأَيۡدِيهِمۡ ثُمَّ يَقُولُونَ هَٰذَا مِنۡ عِندِ ٱللَّهِ﴾⟪2:79⟫، وبالكتاب الثاني التوراة، ونفى\nأن يكون ذلك من الكتاب الذي هو المنزل ﴿وَيَقُولُونَ هُوَ مِنۡ عِندِ ٱللَّهِ﴾⟪3:78⟫\nأي من حكمه وإنزاله، إن قيل: ما فائدة ﴿هُوَ مِنۡ عِندِ ٱللَّهِ﴾⟪3:78⟫ بعد قوله: ﴿لِتَحۡسَبُوهُ مِنَ ٱلۡكِتَٰبِ﴾⟪3:78⟫ أفاد أنهم يشبهون ويروون ذلك.\nوهذا تعريض منهم، وقوله: ﴿وَيَقُولُونَ هُوَ مِنۡ عِندِ ٱللَّهِ﴾⟪3:78⟫ تصريح منهم بالكذب، فوصفهم بأنهم يكذبون\n⟦2:666⟧\nتعريضا وتصريحا، أو تلاوة وتأويلا، وفي هذا دلالة أن إيهام\nالكذب قبيح، كما أن التصريح به قبيح، وأيضا فإن الشيء قد يقال\nهو من عند الله ولا يكون من الكتاب، فإن كل صواب وحكمة\nفمن عند الله، وإن لم يكن منزلا في كتاب، وعلى ذلك قال النبي\n- صلى الله عليه وسلم -: \"إذا أتاكم عني حديث يدل على هدى ويكف عن ردى فاقبلوه، قلته أو لم أقله، فإني قلته\".\nوفائدة ﴿وَيَقُولُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ﴾⟪3:78⟫\n⟦2:667⟧\nبعد الذي تقدم ذكره تنبيا أن كلا الأمرين منهم كذب؛\nلي الألسنة، وقولهم: هو من عند الله، وإعلام أن ليس كذبهم\nمخصوصا بهذين فقط، بل هم كذبة كقولك: فلان تقول على كذا\nوهو كاذب، ثم قال: ﴿وَهُمۡ يَعۡلَمُونَ﴾⟪3:78⟫ تشنيعا عليهم، وأنهم غير\nمعذورين بوجه إذ قد يعذر الإنسان في بعض ما يظنه، ومن كذب\nعامدا إليه وعالما به وهو يقصد به استجلاب نفع دنيوي فهو\nمستحق للذم."}, {"a": [79], "v": 2, "p": 667, "ev": 2, "ep": 675, "sid": 869, "t": "قوله عز وجل: (ما كان لبشر أن يؤتيه الله الكتاب والحكم والنبوة ثم يقول للناس كونوا عبادا لي من دون الله ولكن كونوا ربانيين بما كنتم تعلمون الكتاب وبما كنتم تدرسون (79)\n⟦2:668⟧\nالبشر يستوي فيه الواحد والجمع لكونه كالخلق.\nوالرباني: قيل: هو منسوب إلى الربان، وهو المتخصص بالعلم الذي يربه باستفادته وإفادته، وفعلان أكثر ما يجيء عن فعل للمبالغة نحو نعسان.\nوقال الزجاج: الرباني منسوب إلى الرب، لكن زيد فيه ألف ونون\nللمبالغة في النسبة، كما زيد في: لحياني وجماني قال مؤرج:\nهو لفظة في الأصل سريانية وأخلق بذلك فقل ما يوجد في\n⟦2:669⟧\nكلامهم القديم، وإلى ما قدمنا من معناه\nقال الحسن: معناه: كونوا علماء فقهاء.\nوقال ابن جبير: حكماء فقهاء.\nوقال ابن زيد: مدبري أمر الناس في الولاية بالإصلاح.\nوقال الزجاج: معلمي الناس وهذا كله ألفاظ مختلفة عن\n⟦2:670⟧\nمعنى واحد، بين تعالى أنه لن يصطفي علام الغيوب لرسالته\nمن يعلم من حاله أنه يكذب، وأن يأمر الناس أن يعبدوه.\nوإلى هذا أشار بقوله تعالى: ﴿ٱللَّهُ أَعۡلَمُ حَيۡثُ يَجۡعَلُ رِسَالَتَهُۥۗ﴾⟪6:124⟫.\nوإنما قال: ﴿مَا كَانَ لِبَشَرٍ﴾⟪3:79⟫ فذكر باللام لأن قولك: فلان\nليس له أن يفعل كذلك. أبلغ من قولك: هو لا يفعل؛ لأن في\nقولك ليس له أنه ممنوع منه، إما منعا من خارج كالقهر، وإما من\nداخل من جهة العقل والتزام الشرع، وقد نبه تعالى بذلك أن\nالأنبياء ممنوعون عن ذلك من جهة العقل المسدد، والحظر\nالوارد عليهم من قبله تعالى، لا منعا من جهة عدم التمكن.\nوعلى ذلك قوله تعالى: ﴿وَمَا كَانَ لِنَبِيٍّ أَن يَغُلَّۚ﴾⟪3:161⟫\nوأما قوله: ﴿مَا كَانَ لِلَّهِ أَن يَتَّخِذَ مِن وَلَدٖۖ﴾⟪19:35⟫ فإنه لما أراد تعالى المبالغة في\n⟦2:671⟧\nالنفي أخرج الكلام هذا المخرج، تنبيها أن الحكمة تمنع من\nذلك، وإن كان منزها عن أن يوصف بمنع على وجه.\nوقال الجبائي: ليس قوله: ﴿مَا كَانَ لِبَشَرٍ﴾⟪3:79⟫ على سبيل التحريم.\nلأن هذا محرم على جميع الخلق، قال: ولو كان ذلك تحريما لم يكن\nتكذيبا للنصارى في ادعائهم ذلك على المسيح، لأن من ادعى\nعلى إنسان قولا، فقال: فلان لا يحل له كذا. لا يكون مكذبا\nلدعواه، قال: وإنما أراد الله بهذا القول تكذيبهم، وما قاله\nفيه قصور نظر، فإن النصارى أقروا بأن المسيح لم يكن يدعي ما لم\nيكن له أن يدعي، فإذا أقروا بذلك، وبين تعالى أن ليس له ولا\nلأحد من البشر أن يقول ذلك، كان فيه إلزام واضح، وكأنه قيل:\nقد ثبت أن المسيح لم يكن يدعي ما ليس له دعواه، وثبت أنه كان\nبشرا بما تقدم في هذه السورة وغيرها، ولم يكن لأحد يؤتيه الله\nالكتاب والحكم والنبوة أن يقول للناس: اعبدوني من دون الله.\nوإن المسيح قد أوتي الكتاب والنبوة، فإذن محال أن يدعو أحدا إلى\n⟦2:672⟧\nعبادته، وقوله: ﴿ثُمَّ يَقُولَ لِلنَّاسِ﴾⟪3:79⟫ بالرفع على الاستئناف\nوبالنصب على العطف، أي لا يجتمع الأمران: إثبات النبوة.\nوقوله: ﴿كُونُواْ عِبَادٗا لِّي مِن دُونِ ٱللَّهِ﴾⟪3:79⟫ وقوله: ﴿وَلَٰكِن كُونُواْ رَبَّٰنِيِّـۧنَ﴾⟪3:79⟫، يعني: ولكن يقولوا: كونوا ربانيين، حكماء أولياء لله.\nفقد قيل: إن لم يكن العلماء أولياء لله فليس لله في الأرض ولي.\nوقيل: كونوا متخصصين بالله تخصصا تنسبون إليه، وتوصفون\nبعامة أوصافه نحو الجواد والودود والرحيم.\nوقيل: كونوا من المتخصصين بالله الذين وصفوا بقوله:\n\"فإذا أحببته كنت سمعه الذي يسمع به، وبصره الذي يبصر به \" الخبر.\n⟦2:673⟧\nوقيل: كوثوا متخصصين بالله غر ملتفتين إلى الوسائط\nكأبي بكر لما قال حين موت النبي - صلى الله عليه وسلم -، واضطربت أسرار عامة الناس: \"من كان يعبد محمدا فإن محمدا قد مات، ومن كان يعبد الله فإن الله حي لا يموت \".\nوقد قال تعالى: ﴿وَمَا مُحَمَّدٌ إِلَّا رَسُولٞ قَدۡ خَلَتۡ مِن قَبۡلِهِ ٱلرُّسُلُۚ﴾⟪3:144⟫ الآية، وقوله: ﴿وَبِمَا كُنتُمۡ﴾⟪3:79⟫ أي بكونكم عالمين أو معلمين على حسب القراءتين في تعلمون وتعلمون، ولا تحتاج لفظة ما هاهنا إلى ضمير، كما هو في\nقوله: ﴿فَٱلۡيَوۡمَ نَنسَىٰهُمۡ كَمَا نَسُواْ لِقَآءَ يَوۡمِهِمۡ هَٰذَا﴾⟪7:51⟫، لكونه في\n⟦2:674⟧\nتقدير أن، ومعنى (تعلمون الكتاب) أي تعرفونه كقوله:\n﴿وَلَقَدۡ عَلِمۡتُمُ ٱلَّذِينَ ٱعۡتَدَوۡاْ مِنكُمۡ فِي ٱلسَّبۡتِ﴾⟪2:65⟫.\nوقوله: ﴿وَٱللَّهُ يَعۡلَمُ ٱلۡمُفۡسِدَ مِنَ ٱلۡمُصۡلِحِۚ﴾⟪2:220⟫.\nوإذا قرئ (تعلمون) فمعناه تعلمون الناس الكتاب، وقوله: ﴿وَبِمَا كُنتُمۡ تَدۡرُسُونَ﴾⟪3:79⟫ مما يصح أن يوصف به العلم والمعلم، ومعنى (بما كنتم) أي كونوا معلمي\n⟦2:675⟧\nالخير بما علمتم، أوكونوا حكماء علماء عاملين بما علمتم.\nفإن الحكيم في الحقيقة من عمل بما علم، وكان محكما لعمله\nإحكامه لعلمه.\nوإذا قرئ ﴿بِمَا كُنتُمۡ تُعَلِّمُونَ﴾⟪3:79⟫ فمعناه كونوا\nعاملين بما تعلمون غيركم إشارة إلى فحوى قوله:\n﴿أَتَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبِرِّ وَتَنسَوۡنَ أَنفُسَكُمۡ﴾⟪2:44⟫."}, {"a": [80], "v": 2, "p": 675, "ev": 2, "ep": 676, "sid": 877, "t": "قوله عز وجل: (ولا يأمركم أن تتخذوا الملائكة والنبيين أربابا أيأمركم بالكفر بعد إذ أنتم مسلمون (80)\n(ولا يأمركم) قرئ مرفوعا على الاستئناف، ومنصوبا على رده إلى قوله: ﴿أَن يُؤۡتِيَهُ ٱللَّهُ﴾⟪3:79⟫.\nوفي قراءة عبد الله: \"ولن يأمركم\".\nوقوله: ﴿بَعۡدَ إِذۡ أَنتُم مُّسۡلِمُونَ﴾⟪3:80⟫\n⟦2:676⟧\nأي بعد أن كنتم على دين إبراهيم، أو بعد أن تبعتم النبي فيما\nدعاكم إليه، وهذا كلام يقتضي قياسا بيانه: النبي لا يأمر المسلمين\nبالكفر، وهذه مقدمة دل عليها قوله: ﴿أَيَأۡمُرُكُم بِٱلۡكُفۡرِ﴾⟪3:80⟫.\nلأن هذا الإنكار يقتضي أبلغ نفي والأمر باتخاذ النبيين والملائكة\nأربابا أمر با لكفر، فإذن لا يكون ذلك من الأنبياء."}, {"a": [81], "v": 2, "p": 677, "ev": 2, "ep": 684, "sid": 879, "t": "قوله عز وجل: (وإذ أخذ الله ميثاق النبيين لما آتيتكم من كتاب وحكمة ثم جاءكم رسول مصدق لما معكم لتؤمنن به ولتنصرنه قال أأقررتم وأخذتم على ذلكم إصري قالوا أقررنا قال فاشهدوا وأنا معكم من الشاهدين (81)\nقوله: ﴿لَمَآ ءَاتَيۡتُكُم﴾⟪3:81⟫ إذا قرئ بالفتح فلفظة ما تحتمل وجهين.\nأحدهما: أن تكون موصولا وتقديره: ما أتيتكموه، كقوله: ﴿أَهَٰذَا ٱلَّذِي بَعَثَ ٱللَّهُ رَسُولًا﴾⟪25:41⟫ أي بعثه الله، والراجع إليه من قوله: ﴿ثُمَّ جَآءَكُمۡ رَسُولٞ مُّصَدِّقٞ لِّمَا مَعَكُمۡ﴾⟪3:81⟫ أحد شيئين: إما محذوف، أي جاءكم\nرسول به، وإما لأن قوله: ﴿لِّمَا مَعَكُمۡ﴾⟪3:81⟫ هو في المعنى: الكتاب\n⟦2:678⟧\nفاستغنى به عن الضمير، كقولك: الذي أتاني لا أضرب عمرا.\nإذا كان عمرو هو الذي أتاه، وهذا أجازه الأخفش، وعليه\nحمل قوله تعالى: ﴿إِنَّهُۥ مَن يَتَّقِ وَيَصۡبِرۡ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ﴾⟪12:90⟫\nأي لا يضيع أجرهم، وجاز ذلك لما كان من يتقي ويصبر هم المحسنون. والوجه الثاني: أن تكون ما للجزاء وتكون مفعولا من (آتيتكم)، و (جاءكم) في موضع الجزم معطوف عليه، واللام الداخلة على (ما) هي الموطئة للقسم،\n⟦2:679⟧\nوالتي في ﴿لَتُؤۡمِنُنَّ بِهِۦ وَلَتَنصُرُنَّهُۥۚ﴾⟪3:81⟫ للقسم كاللامين في قوله تعالى:\n﴿وَلَئِن شِئۡنَا لَنَذۡهَبَنَّ بِٱلَّذِيٓ﴾⟪17:86⟫، وعلى هذا حمل سيبويه\nالآية، وقال: وسألته - يعني الخليل - عن قوله: ﴿وَإِذۡ أَخَذَ ٱللَّهُ﴾⟪3:81⟫\nفقال ما هاهنا بمنزلة الذي، ودخلتها اللام كما دخلت على\nإن حين قلت: لئن فعلت لأفعلن . وعنى بقوله: إن ما بمنزلة\nالذي، أنه اسم لا حرف، كما هو حرف في قوله: ﴿لَمَّا مَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ﴾⟪43:35⟫، ولم يرد أنها موصولة كالذي، وإنما لم يجعله\nكالذي لعدم الضمير الراجع إليه في قوله: ﴿ثُمَّ جَآءَكُمۡ رَسُولٞ﴾⟪3:81⟫\n⟦2:680⟧\nفإن قيل: فمن جعل ما موصولا في قوله: ﴿لَمَآ ءَاتَيۡتُكُم مِّن كِتَٰبٖ وَحِكۡمَةٖ﴾⟪3:81⟫ وجب أن يكون ابتداء، فما خبره؟\nقيل: خبره (لتؤمنن به)، والضمير في (به) هو راجع\nإلى ما، وفي قو له. (ولتنصرنه) إلى الر سول، ولا يجوز أن يرجع\nفي قوله ﴿لَتُؤۡمِنُنَّ بِهِۦ﴾⟪3:81⟫ إلى الرسول أيضا، لأنه يبقى المبتدأ بلا\nعائد إليه، فأما من جعل (ما) جرا فلا يحتاج إلا ضمير، لأنه حينئذ\nمفعول، والمفعول لا يحتاج إلى ضمير يرجع إليه، وأما من قرأ\n\"لما أتيتكم\" بالكسر فمعناه: أخذ الله الميثاق منهم لأجل الذي\nآتيتكم، وما لا تكون هاهنا إلا موصولة، والكلام في رجوع\nالضمير إليه قد تقدم وقرى \"لما آتيتكم\" أي أخذ الله ميثاق\n⟦2:681⟧\nالنبيين حين آتيتكم الكتاب، ثم جاءكم رسول، ولما ذكر حكى\nلفظ الميثاق المأخوذ عليهم أي، قوله: ﴿لَتُؤۡمِنُنَّ بِهِۦ وَلَتَنصُرُنَّهُۥۚ﴾⟪3:81⟫ إلى قوله: ﴿مِّنَ ٱلشَّٰهِدِينَ﴾⟪3:81⟫.\nواختلف فيمن أخذ عليه الميثاق، فقال بعضهم: أخذ من الذين منهم الأنبياء، وتقدير الكلام أخذ الله ميثاق أمم النبيين.\nوروي أن الربيع قرأ \"وإذا أخذ الله ميثاق الذين أوتوا الكتاب.\nوقال: هكذا أنزل وأخطأ الكاتب، ألا ترى أنه قال: ﴿ثُمَّ جَآءَكُمۡ رَسُولٞ﴾⟪3:81⟫،\n⟦2:682⟧\nوحكي أنه هكذا في قراءة ابن مسعود، وقال بعضهم: أخذ\nميثاق النبيين أن يبشر المتقدم بالمتأخر، ويصدق المتأخر\n⟦2:683⟧\nالمتقدم، وأن يخبروا كلهم بكون محمد خاتم النبيين.\nقال السدي: ما بعث نبي من لدن نوح إلا أخذ ميثاقه لتؤمنن بمحمد\nإن خرج وهو حي، وفي هذا تنبيه أن كل زمان بالشريعة التي\nخصه الله بها أولى، ولهذا قال النبي - صلى الله عليه وسلم -:\n\"لو كان موسى حيا لما وسعه إلا اتباعي \".\nوالصحيح أن العهد مأخوذ من الفريقين من الرسل والمرسل إليهم، لكن خص الأنبياء بالذكر لكونهم الرؤوس وكون الأمة تبعا لهم، وكذلك خص النبي في كثير من المخاطبة التي تشاركه فيها أمته نحو ﴿يَٰٓأَيُّهَا ٱلنَّبِيُّ إِذَا طَلَّقۡتُمُ﴾⟪65:1⟫،\n⟦2:684⟧\nولأنه إذا أخذ الميثاق على الأنبياء فقد أخذ على أممهم لمشاركتهم\nأنبياءهم في عامة ما شرع لهم، وأما كيفية أخذ هذا العهد، فقد\nقيل: كان ذلك بقول وأمر من الله للأنبياء بأن يخبروا قومهم\nبذلك، وقد قيل: إن ذلك بما ضمنه عقولهم أن الحق حيث ما وجد\nيجب أن يتبع، ولما أخبر الله تعالى في الآية المتقدمة أن ليس لأحد\nما ادعاه من قوله: ﴿مَا كَانَ لِبَشَرٍ أَن يُؤۡتِيَهُ ٱللَّهُ ٱلۡكِتَٰبَ وَٱلۡحُكۡمَ﴾⟪3:79⟫\nذكر هاهنا أنه تعالى لم يخل الأنبياء مع كونهم مأمونين\nعلى الغيب من أخذ ميثاقهم بمظاهرة البعض البعض.\nوقوله: (فاشهدوا) قيل معناه اعلموا، فإن الشهادة وقت التحمل هو\nالعلم، ووقت الإقامة هو الإخبار، وقوله: ﴿وَأَنَا۠ مَعَكُم مِّنَ ٱلشَّٰهِدِينَ﴾⟪3:81⟫\nعلى حد ما تقدم في قوله: ﴿شَهِدَ ٱللَّهُ﴾."}, {"a": [82], "v": 2, "p": 685, "ev": 2, "ep": 685, "sid": 887, "t": "قوله عز وجل: (فمن تولى بعد ذلك فأولئك هم الفاسقون (82)\nلما كان الفسق هو الخروج عن أمر الله وطاعته، وكان بين أدنى\nمنزلة وبين أقصاها بون بعيد صار له منازل كثيرة، فيطلق تارة\nعلى الذنب الصغير، نحو قوله: ﴿وَلَا يُضَآرَّ كَاتِبٞ وَلَا شَهِيدٞۚ وَإِن تَفۡعَلُواْ فَإِنَّهُۥ فُسُوقُۢ بِكُمۡۗ﴾⟪2:282⟫، وتارة على الكفر والشرك، نحو\n﴿أَفَمَن كَانَ مُؤۡمِنٗا كَمَن كَانَ فَاسِقٗاۚ﴾⟪32:18⟫، وقوله: ﴿وَأَمَّا ٱلَّذِينَ فَسَقُواْ فَمَأۡوَىٰهُمُ ٱلنَّارُۖ﴾⟪32:20⟫، وعلى هذا استعمال الفاسقين هاهنا).\nودخول الفاء في قوله فاولئك لتضمن (من) معنى الشرط."}, {"a": [83], "v": 2, "p": 685, "ev": 2, "ep": 689, "sid": 887, "t": "قوله عز وجل: (أفغير دين الله يبغون وله أسلم من في السماوات والأرض طوعا وكرها وإليه يرجعون (83)\nحمل (أسلم) على الاستسلام وعلى الاعتقاد والإقرار باللسان،\n⟦2:686⟧\nوالتزام الأحكام، وقيل في ذلك أقوال:\nالأول: له أسلم من في السموات طوعا، وهو أن علمهم بوحدانية الله وصفاته ضرورة لا استدلال، وعامة أهل الأرض كرها بمعنى أن الحجة\nأكرهتهم وألجأتهم كقولك: الدلالة أكرهتني على القول بهذه\nالمسائل، وليس هذا من الكره المذموم.\nالثاني: أسلم المؤمنون له طوعا، والكافرون كرها، إذ لم يقدروا على أن يمتنعوا عليه مما يريده بهم، ويقضيه عليهم .\nالثالث: عن قتادة: أسلم المؤمنون له طوعا في حال الصحة والأمن، والكافرون كرها عند الموت،\n⟦2:687⟧\nحيث قال: ﴿فَلَمۡ يَكُ يَنفَعُهُمۡ إِيمَٰنُهُمۡ لَمَّا رَأَوۡاْ بَأۡسَنَاۖ﴾⟪40:85⟫.\nالرابع: عنى بالكره من قوتل، وألجى إلى أن يؤمن.\nالخامس: عن أبي العالية ومجاهد أن كلا أقر بخلقه إياهم، وإن أشركوا\nمعه، لقوله: ﴿وَلَئِن سَأَلۡتَهُم مَّنۡ خَلَقَهُمۡ لَيَقُولُنَّ ٱللَّهُۖ﴾⟪43:87⟫.\nالسادس: عن ابن عباس: أسلموا باحوالهم الناطقة جميهم.\nوذلك في الذرء الأول)، حين قال: ﴿أَلَسۡتُ بِرَبِّكُمۡۖ قَالُواْ بَلَىٰ﴾⟪7:172⟫\n⟦2:688⟧\nوقيل: معنى ذلك دلائلهم التي فطروا عليها، التي هي العقل\nوالتمييز المقتضيان لإسلامهم طوعا أو كرها، وإلى هذا أشار\nبقوله: ﴿وَظِلَٰلُهُم بِٱلۡغُدُوِّ وَٱلۡأٓصَالِ۩﴾⟪13:15⟫.\nالسابع: عن بعض الصوفية أن من أسلم طوعا هو من طالع المثيب والمعاقب دون الثواب والعقاب، فأسلم رغبة ورهبة، ونحو هذه الآية\nقوله: ﴿وَلِلَّهِۤ يَسۡجُدُۤ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ طَوۡعٗا وَكَرۡهٗا﴾⟪13:15⟫\nوفي هذه الآية حجة بينة أن طاعة الله هي التي يجب أن تكون المبتغى والمطلوب،\n⟦2:689⟧\nلأن كل ما سواه مما يتقرب إليه، فقد أسلم لله طوعا أو كرها."}, {"a": [84], "v": 2, "p": 689, "ev": 2, "ep": 691, "sid": 891, "t": "قوله عز وجل: (قل آمنا بالله وما أنزل علينا وما أنزل على إبراهيم وإسماعيل وإسحاق ويعقوب والأسباط وما أوتي موسى وعيسى والنبيون من ربهم لا نفرق بين أحد منهم ونحن له مسلمون (84)\nقد تقدم القول في ذلك في سورة البقرة إلا أنه\nيقال: كيف قال هاهنا: (قل) وهناك: (قولوا)، وذكر هاهنا\n(علينا) وثم (إلينا)، وذكر هناك ﴿وَمَآ أُوتِيَ ٱلنَّبِيُّونَ﴾⟪2:136⟫.\nوترك ما أوتى هاهنا؟\nوالجواب: أن (قل) هاهنا خطاب للنبي - صلى الله عليه وسلم - بأن يعتقد ذلك ويبلغ قومه، وهناك خطاب للأمة أن يعتقدوا\nوليس يأمرهم أن يبلغوا، وإنما قال هاهنا (على) لأن ذلك لما\nكان خطابا للنبي - صلى الله عليه وسلم - وكان واصلا إليه من الملأ الأعلى بلا واسطة بشرية، كان لفظ على المختص بالعلو أولى به، وهناك لما كان\nخطابا للأمة، وقد وصل إليهم بوساطة النبي - صلى الله عليه وسلم - كان لفظ إلى المختص بالإيصال أولى، ويجوز أن يقال: أنزل عليه إنما يحمل\n⟦2:690⟧\nعلى ما أمر المنزل عليه أن يبلغ غيره، وأنزل إليه على ما خص به\nفي نفسه، وإليه نهاية الإنزال وعلى ذلك قال: ﴿أَوَلَمۡ يَكۡفِهِمۡ أَنَّآ أَنزَلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ يُتۡلَىٰ عَلَيۡهِمۡۚ﴾⟪29:51⟫، وقال: ﴿وَأَنزَلۡنَآ إِلَيۡكَ ٱلذِّكۡرَ لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيۡهِمۡ﴾⟪16:44⟫ فخص بإلى هاهنا لما كان مخصوصا بالذكر الذي هو بيان المنزل، وهذا كلام أي الأولى، لا في الوجوب، وأما إعادة لفظ (ما أوتي) هناك فلأنه لما كان لفظ الخطاب عاما، ومن حكم خطاب العامة البسط دون الإيجاز\nبسط اللفظ، ولما كان الخطاب هاهنا خاضا للنبي - صلى الله عليه وسلم - على ما قدمنا اكتفى فيه بالإيجاز.\nوإن قيل: إذا كان ذلك أمرا للنبي - صلى الله عليه وسلم - أن\nيقوله، فكيف قال: ﴿وَنَحۡنُ لَهُۥ مُسۡلِمُونَ﴾⟪3:84⟫؟\nقيل: إنما ذكر ذلك تنبيها أن أمته غير منفردين عنه في هذا الاعتقاد، وغير مكروه لهم أن يبلغوا ذلك تبليغ النبي - صلى الله عليه وسلم -\nفكيف فسح لهم التبجح بذلك مع كون التبجح مذموما؟\nقيل: التبجح هو إظهار الإنسان\n⟦2:691⟧\nما يتطلب به رفعة عند الناس، وليس هذا من ذلك، بل هو\nإظهار التحمد المندوب إليه بقوله ﴿وَأَمَّا بِنِعۡمَةِ رَبِّكَ فَحَدِّثۡ﴾⟪93:11⟫.\nوإظهار مباينة الكفار بالاعتراف بالإسلام، وقصد أن الاستسلام\nفي الإيمان بهم هو في الحقيقة لله تعالى لا لغيره."}, {"a": [85], "v": 2, "p": 691, "ev": 2, "ep": 692, "sid": 893, "t": "قوله عز وجل: (ومن يبتغ غير الإسلام دينا فلن يقبل منه وهو في الآخرة من الخاسرين (85)\nفي الآية قولان: أحدهما: أن الأسلام هاهنا الاستسلام إلى الله.\nوتفويض الأمر إليه، وذلك أمر مراد من الناس في كل زمان\nومن كل أمة وفي كل شريعة، وقد\n⟦2:692⟧\nتقدم أن الدين في اللغة الطاعة وفي التعارف: وضع إلهي\nينساق به الناس إلى النعيم الدائم، فبين تعالى أن من تحرى\nطاعة وانسياقا إلى النعيم من غير الاستسلام له على ما يأمره به.\nويصرفه فيه فلن يقبل منه دنيء من أعماله، وهو في الآخرة من\nالذين خسروا أنفسهم.\nوالثاني: أن المراد بالإسلام شريعة محمد عليه الصلاة والمسلام، فبين أن من تحرى بعد بعثته شريعة أو طاعة لله من غير متابعته في شريعته فغير مقبول منه، وهذا الوجه داخل في الأول، فمعلوم أن من الاستسلام الانقياد لأوامر من\nصحت نبوته وظهر صدقه."}, {"a": [86], "v": 2, "p": 692, "ev": 2, "ep": 699, "sid": 894, "t": "قوله عز وجل: (كيف يهدي الله قوما كفروا بعد إيمانهم وشهدوا أن الرسول حق وجاءهم البينات والله لا يهدي القوم الظالمين (86)\n⟦2:693⟧\nهذه الآية واللتان بعدها، قيل: نزلت في رجل ارتد.\nثم أرسل إلى قومه: اسالوا النبي - صلى الله عليه وسلم - هل لي من توبة؟ فأنزل\nالله تعالى ذلك، فعاد إلى الإسلام وحسن إسلامه.\nوقيل: نزلت في اليهود، الذين اعترفوا بنبوة محمد - صلى الله عليه وسلم - قبل بعثته، ثم أنكروه بعدها، فعلى هذا قوله: ﴿كَفَرُواْ بَعۡدَ إِيمَٰنِهِمۡ﴾⟪3:86⟫ أي\n⟦2:694⟧\nجحدوا بعد معرفتهم، لا أنهم ارتدوا بعد دخولهم في الإسلام.\nوقد تقدم أن الهداية من الله على أضرب: الهداية التي عم\nبها كل مكلف، وهو إعطاؤه العقل المميز بين الخير والشر وبين\nالصدق والكذب، وهي المعني بقوله: ﴿وَأَمَّا ثَمُودُ فَهَدَيۡنَٰهُمۡ فَٱسۡتَحَبُّواْ ٱلۡعَمَىٰ عَلَى ٱلۡهُدَىٰ﴾⟪41:17⟫.\nوالثاني: \"زيادة الهدى التي تأتي بقدر استعمال الأول العني بقوله: ﴿وَٱلَّذِينَ ٱهۡتَدَوۡاْ زَادَهُمۡ هُدٗى﴾⟪47:17⟫\n⟦2:695⟧\nوالثالث: التزكية لأعمالهم أو توفيقه في أحوالهم.\nوهو المعني بقوله: ﴿إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ يَهۡدِيهِمۡ رَبُّهُم بِإِيمَٰنِهِمۡۖ﴾⟪10:9⟫، والرابع: إدخال الجنة المعني بقوله: (والذين قتلوا في سبيل الله فلن يضل أعمالهم (4) سيهديهم ويصلح بالهم (5) ويدخلهم الجنة عرفها لهم (6)\nوالله تعالى لا يؤتي هؤلاء شيئا من ذلك).\nأما الثاني والثالث والرابع فلأنهم لا يستحقونه إذ لم يهتدوا بالأول.\nوأما الأول فلأنهم قد أتاهم ما أمكنهم الاهتداء به.\nومن أوتي من الهداية ما فيه من الكفاية فلم يهتد به،\n⟦2:696⟧\n2271 ب\nفالزيادة لا تغني ما لم تكن على سبيل القهر المنافي للتكليف.\nولذلك قال تعالى: ﴿وَلَوۡ أَنَّنَا نَزَّلۡنَآ إِلَيۡهِمُ ٱلۡمَلَٰٓئِكَةَ وَكَلَّمَهُمُ ٱلۡمَوۡتَىٰ وَحَشَرۡنَا عَلَيۡهِمۡ﴾⟪6:111⟫ الآية.\nثم قال: ﴿وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ﴾⟪3:86⟫ تنبيها أن الهداية من الله.\nوالظلم من العبد، يتنافيان ولا يجتمعان.\nفإن الظلم ترك الاهتداء، ومن يهدى ويترك الاهتداء عنادا\nلا سبيل إلى هدايته إلا قهرا.\nوعلى هذا قال: (إن الذين كفروا وظلموا لم يكن الله ليغفر لهم ولا ليهديهم طريقا (168).\nإن قيل: كيف نفى عن الكافر الهداية في هذه المواضع.\nوأثبت له في قوله: ﴿وَأَمَّا ثَمُودُ فَهَدَيۡنَٰهُمۡ﴾⟪41:17⟫؟\nقيل: المتبت لهم هاهنا هو العقل والتمييز دون الأخرى، التي لا\nتحصل إلا بعد الاهتداء بهذا، وهذه تارة تثبت للكافر إذا\n⟦2:697⟧\nأريد أنه مطبوع عليها ومعرض لاستعماله إياها، وتارة تنفى\nعنه، بمعنى أنه لم يستعملها، ولم يحصل قبوله على ما يحب.\nفكأنه في حكم ما لم يعط.\nوقوله: ﴿لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ﴾⟪3:86⟫ فهو على لفظ الاستقبال.\nومعناه لا يفعل به ذلك ثانيا، إذ قد أتاه ما فيه الكفاية.\nولفظ (كيف) وإن كان استفهام، فالقصد به\n⟦2:698⟧\nالنفي هاهنا، وعلى هذا قول الشاعر:\n. . . . . . . . . . . . . . . . . . . . . .. ألا هل أخو عيش لذيذ بدائم\nفأدخل الباء في خبر هل لما أراد معنى ليس، إن قيل: على ماذا\nعطف قوله: (وشهدوا) فإن ظاهره من حيث المعنى أنه معطوف\nعلى قوله ﴿بَعۡدَ إِيمَٰنِهِمۡ﴾⟪3:86⟫، لا يصح عطف الفعل على الاسم.\nولا يصح أن يكون معطوفا على قوله: ﴿يَهۡدِي ٱللَّهُ﴾⟪3:86⟫، لأنه لم\nيرد كيف يهدي الله قوما هكذا وكيف شهدوا أن الرسول حق؟\nقيل: في ذلك وجهان: أحدهما: أن يكون تقديره بعد إيمانهم\nوإن شهدوا، فيكون أن مقدرا، كما هو في قول الشاعر:\n⟦2:699⟧\nللبس عباءة وتقر عيني. . .\nإلا أن إضمار أن في البيت أظهر لانتصاب تقر.\nوالثاني: أن يكون (وشهدوا) في موضع الحال.\nأي وقد شهدوا، نحو قوله: ﴿أَوۡ جَآءُوكُمۡ حَصِرَتۡ صُدُورُهُمۡ﴾⟪4:90⟫\nوقول الشا عر:\nتقول وصكت نحرها بيمينها. . . . . . . . . . . . . . . . . . . . . ..\nوقوله: ﴿أَنَّ ٱلرَّسُولَ حَقّٞ﴾⟪3:86⟫ أي أنه سيبعث، وأنه منتظر."}, {"a": [87, 88], "v": 2, "p": 700, "ev": 2, "ep": 700, "sid": 902, "t": "قوله عز وجل: (أولئك جزاؤهم أن عليهم لعنة الله والملائكة والناس أجمعين (87) خالدين فيها لا يخفف عنهم العذاب ولا هم ينظرون (88)\nقد تقدم الكلام في ذلك في قوله: ﴿إِنَّ ٱلَّذِينَ كَفَرُواْ وَمَاتُواْ وَهُمۡ كُفَّارٞ﴾\nإلا أنه بت الحكم، ثم قال: ﴿عَلَيۡهِمۡ لَعۡنَةَ﴾⟪3:87⟫\nلما كان ذلك حكما على قوم ماتوا على الكفر، وقال هاهنا:\n(جزاؤهم) لما كان حكما على قوم باقين يرجى صلاحهم تنبيها\nعلى تضمن معنى الشرط، لأن ذلك لهم إن ماتوا على الكفر."}, {"a": [89], "v": 2, "p": 700, "ev": 2, "ep": 705, "sid": 902, "t": "قوله عز وجل: (إلا الذين تابوا من بعد ذلك وأصلحوا فإن الله غفور رحيم (89)\nإن قيل: \" لم اقتصر هاهنا على التوبة والإصلاح.\nوقال في البقرة: ﴿إِلَّا ٱلَّذِينَ تَابُواْ وَأَصۡلَحُواْ وَبَيَّنُواْ﴾⟪2:160⟫ أن\n⟦2:701⟧\nيعفي المذنب ما تقدم من ذنبه بما يوفى عليه من أفعاله الخير، وكان من\nذنب الأحبار الذين ذكرهم في قوله: ﴿إِنَّ ٱلَّذِينَ يَكۡتُمُونَ مَآ أَنزَلۡنَا مِنَ ٱلۡبَيِّنَٰتِ﴾⟪2:159⟫، أن قالوا للناس: ليس في التوراة ما يدل على نبوة محمد.\nفصار من تمام توبتهم أن يبينوا للناس ما كتموه، ولما لم يكن في الموضعين\nها هنا ذلك اقتصر في توبتهم على الإصلاح.\nوإنما أتبع التوبة في\n⟦2:702⟧\nعامة المو اضع الإصلاح، فإن التوبة راجعة في الأصل إلى الاعتقاد\nوالإصلاح إلى الأعمال. وكلاهما مرادان، وعلى ذلك اتباع\nعمل الصالحات بعد الإيمان في كل موضع ذكرا معا.\nإن قيل: لم قال ها هنا: (غفور رحيم) وقال ثم: ﴿وَأَنَا ٱلتَّوَّابُ ٱلرَّحِيمُ﴾⟪2:160⟫ و؟ قيل: كل واحدة من الصفتين؛ أعني التواب\n⟦2:703⟧\nوالغفور يتضمن الأخرى، لكن التواب أخص والغفور\nأعم، فذكر حيث ما ذكر أعظم الذنبين الضلال والإضلال\nالتواب، وحيث ما ذكر أصغرهما - وهو الضلال دون الإضلال -\nذكر الغفور.\nإن قيل: لم قال ههنا: ﴿مِنۢ بَعۡدِ ذَٰلِكَ﴾⟪3:89⟫ ولم يقل ثم؟\nقيل: لما وصف ههنا قوما كان منهم إيمان متقدم.\nثم حصل منهم كفر بعد إيمانهم، قال: ﴿مِنۢ بَعۡدِ ذَٰلِكَ﴾⟪3:89⟫ ليبين أن\nالإيمان المتقدم لا ينفعهم إذ قد أحبطوه وأبطلوه، وأن الذي\nيعتد به هو ما يفعلونه من بعد،\n⟦2:704⟧\nولما لم يكن ثم كفر بعد إيمان متقدم استغنى عن ذكر (بعد ذلك).\n⟦2:705⟧\nودخول الفاء في قوله: ﴿فَإِنَّ ٱللَّهَ﴾⟪3:89⟫ لتضمن الكلام معنى\nالجزاء، كأنه قيل: إن تابوا وأصلحوا يغفر لهم."}, {"a": [90], "v": 2, "p": 705, "ev": 2, "ep": 708, "sid": 907, "t": "قوله تعالى: (إن الذين كفروا بعد إيمانهم ثم ازدادوا كفرا لن تقبل توبتهم وأولئك هم الضالون (90)\n⟦2:706⟧\nقيل: معناه لن تقبل توبتهم بعد الموت.\nوقيل: عند الموت والمعاينة، نحو ﴿وَلَيۡسَتِ ٱلتَّوۡبَةُ لِلَّذِينَ يَعۡمَلُونَ ٱلسَّيِّـَٔاتِ حَتَّىٰٓ إِذَا حَضَرَ أَحَدَهُمُ ٱلۡمَوۡتُ قَالَ إِنِّي تُبۡتُ ٱلۡـَٰٔنَ﴾⟪4:18⟫\nوقيل: توبتهبم المتقدمة فإن تلك أحبطها الكفر المتعقب.\nوقيل: نزل في قوم ارتدوا.\nسورة آل عمر ان، الآية: 90.\nوهذا مووي عن مجاهد انظر: زاد المسير (1 419)، والبحر المحيط\n(2 542). وقد رذ الطبري ذلك قاثلا: \"أنكرنا ذلك، لأن التوبة من\nالعبد غير كاثنة إلا في حال حياته، فأما بعد مماته فلا توبة). جامع البيان\n(6 583).\nوهذا قول الحسن وقتادة والسدي، وهو مووى عن مجاهد أيضا، انظر:\nجامع البيان (6 578، 579)، والوسيط (1 1 46)، ومعالم التنزيل\n(2 65)، ز زاد المسير (1 419)، والبحر المحيط (2 542)، وتفسير\nالقرآن العظيم لابن كثير (1 359)، وقد رد ابن جرير الطبري هذا\nالقول أيضا مبئنا أنه لا خلاف في أن ك) افرا لو أسلم قبل خروج نفسه\nبطرفة عين، أن حكمه حكم المسلمين في الصلاة عليه والموارثة وساثر\nالأحكام مما يدل على صحة إسلامه. جامع البيان (6 583).\nسورة النساء، الآية: 18.\nوهذا مروي عن عكرمة وابن جريج انظر: جامع البيان (6 580.\n581) والبحر المحيط (2 542). قال الطبري:. \"وأما قول من زعم أن\nمعنى ذلك: التوبة التي كانت قبل الكفر فقول لا معنى له، لأن الله عز وجل=\n706\n⟦2:707⟧\nوقالوا: إنا إذا رجعنا قبل توبتنا. وظنوا أن ذلك منهم توبة.\nفبين تعالى أن هذه النية غير مقبولة، وأنها ضلالة.\nوقيل: معناه: لا تكون منهم توبة مقبولة، كقول الشاعر:\nعلى لاحب لا يهتدى بمناره. . .\nأي لا يكون فيه منار فيهتدى به، وهذا إخبار عن علمه\n⟦2:708⟧\nتعالى بحالهم، وقيل: إن توبتهم غير مقبولة في حال ما هم\nضالون، فالتوبة والضلال متنافيان لا يجتمعان، فالواو في قوله:\n(وأؤلئك) على هذا واو الحال."}, {"a": [91], "v": 2, "p": 708, "ev": 2, "ep": 710, "sid": 910, "t": "قوله تعالى: (إن الذين كفروا وماتوا وهم كفار فلن يقبل من أحدهم ملء الأرض ذهبا ولو افتدى به أولئك لهم عذاب أليم وما لهم من ناصرين (91).\nالفدية: بذل شيء احتراسا من أذى، ومنه فداء الأسير.\nوقولهم: فديتك. وإدخال الواو في قوله: ﴿وَلَوِ ٱفۡتَدَىٰ بِهِۦٓۗ﴾⟪3:91⟫\n⟦2:709⟧\nلعموم المعنى، ومعناه لا يقبل منهم ذلك وإن أخرجه على\nوجه القربة في الدنيا، إذ كان لا يتقبل الله إلا من المتقين.\nويجوز أن يعني ذلك في الآخرة، ومعناه: لو ملك ذلك فأخرجه\nلم يكن ينفعه ، وليست الواو بزائدة كما ظن بعضهم، لأنه\n⟦2:710⟧\nحينئذ يسقط معنى عموم الحالين، وملء الأرض - قيل: هو\nمقدار ما يملأ الأرض، وقيل: معناه كل ما يتعامل به في\nالأرض من الذهب، وذلك حسم لطمع من مات على كفره في رحمته.\nوقيل: وهذه الآية والتي قبلها كالآيتين في سورة النساء (إنما التوبة على الله للذين يعملون السوء بجهالة ثم يتوبون من قريب .. + إلى آخر الآيتين."}, {"a": [92], "v": 2, "p": 710, "ev": 2, "ep": 715, "sid": 912, "t": "قوله تعالى: (لن تنالوا البر حتى تنفقوا مما تحبون وما تنفقوا من شيء فإن الله به عليم (92)\n⟦2:711⟧\nالبر: التوسع في فعل الخير، وقد تقدم في قوله: ﴿أَتَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبِرِّ﴾⟪2:44⟫\nإن البر ينسب إلى العبد تارة، وذلك إذا أطاع الله.\nوإلى الله تارة إذا أنعم على العبد.\nوقد حمل ههنا على الأمرين، فقيل: البر من الله الثواب.\nوقيل: الجنة، وقيل: الطاعة، ومن الناس من اعتبر ذلك\nفي المال فقط، فالإنسان محب للمال بالطبع، ولهذا قال تعالى:\n⟦2:712⟧\n﴿وَتُحِبُّونَ ٱلۡمَالَ حُبّٗا جَمّٗا﴾⟪89:20⟫، ثم منهم من قال: هذا خطاب\nللأغنياء، ولذلك قال الحسن: عنى الزكاة الواجبة وما فرض في\nالأموال خاصة، ومنهم من قال: خطاب للكل، وحث لهم على ما قدروا عليه من الإنفاق، وكمن مدح يقوله: ﴿وَيُؤۡثِرُونَ عَلَىٰٓ أَنفُسِهِمۡ﴾⟪59:9⟫، ولذلك لما نزلت هذه الآية جاء زيد بن حارثة بفرس، فقال: هذا مما أحبه الله، وقد جعلته في سبيل الله، فحمل\n⟦2:713⟧\nعليه رسول الله - صلى الله عليه وسلم - أسامة، ومنهم من اعتبر ذلك في متاع الحياة الدنيا كله، فقال: لن تنالوا البر إلا بالإنفاق، وبذل الجاه\nوالبدن والنفس، قال: وذلك حث على جميع المحامد، فإن\nمن تشجع وبذل المهجة في طاعة الله فقد أنفق ما أحب،\n⟦2:714⟧\nولذلك قيل:\n. . . . . . . . . . . . . . . . . . . . . . الجود بالنفس أقصى غاية الجود\nوقال بعضهم: أحب الأشياء إليك روحك، فأنفقها في الوصول\nإلى البر.\nوقيل: بر الله لعبده اطلاعه على دقائق حكمته وحقائق\nالمعقولات، ولا يكون ذلك إلا بترك ما تميل إليه النفوس من\nالمحسوسات من المطعم والمنكح والملبس.\nوقيل: أعظم البر مجاورة البار وقربه، وذلك بإنفاق ما لنا في الدنيا .\nوقوله:\n⟦2:715⟧\n﴿فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٞ﴾⟪3:92⟫ أي مجازيكم، ولدلالة ذلك على المجازاة\nجعل جوابا للشرط."}, {"a": [93], "v": 2, "p": 715, "ev": 2, "ep": 722, "sid": 917, "t": "قوله تعالى: (كل الطعام كان حلا لبني إسرائيل إلا ما حرم إسرائيل على نفسه من قبل أن تنزل التوراة قل فأتوا بالتوراة فاتلوها إن كنتم صادقين (93)\nكان اليهود أنكروا تحليل النبي - صلى الله عليه وسلم - لحوم الإبل، وقالوا: إنها كانت محرمة على إبراهيم على ما نطقت به التوراة، فكذبهم تعالى، وذكر أنها كانت محللة عليه وعلى أولاده إلى أن حرمها إسرائيل على نفسه، وهو يعقوب، - وأمرهم بإحضار التوراة، فامتنعوا، ولم يجسروا على ذلك،\n⟦2:716⟧\nلصدق ما أخبر تعالى به، وسبب تحريمه ذلك - قيل: إنما كان\nمرضا أورثه لحم الإبل فتركه، وحرمه على نفسه تحريم المريض\nطعاما لا يوافقه، لا تحريم شرع.\nوقال ابن عباس والحسن: أصابه عرق النسا، فنذر أن يترك إن عافاه الله أشهى طعام إليه تقربا إلى الله تعالى، وتحريم اليهود ذلك كان اقتداء منهم به،\n⟦2:717⟧\nوقيل: إنه لما حرم على نفسه حرم الله عليهم، ولذلك قال:\n﴿فَبِظُلۡمٖ مِّنَ ٱلَّذِينَ هَادُواْ حَرَّمۡنَا عَلَيۡهِمۡ طَيِّبَٰتٍ﴾⟪4:160⟫ في الآية حجة\nعليهم على هذا في جواز النسخ، لأنه حرم عليهم ما كان مباحا\nفي شريعة إبراهيم.\nإن قيل: كيف حرم هو على نفسه ما كان\n⟦2:718⟧\nمباحا فأقره الله عليه، وحرم النبي - صلى الله عليه وسلم - جاريته فعاتبه ومنعه؟\nقيل: إن إسرائيل إما أنه حرم على نفسه لحم الإبل، لأنه لم يكن يوافقه.\nوكان واجبا عليه تركه.\nفإن الله تعالى جعل الطعام ليتوصل به إلى صلاح البدن.\nوما يؤدي إلى فساده فواجب علينا تركه؟ وإما أنه حرم ذلك تقربا إلى الله كما يحرم الصائم الطعام، وكما يحرم المعتكف على نفسه بعض التصرفات، ولم يكن تحريم النبي - صلى الله عليه وسلم - علي أحد هذين الوجهين، بل لما ذكره تعالى: ﴿تَبۡتَغِي مَرۡضَاتَ أَزۡوَٰجِكَۚ﴾⟪66:1⟫، ولأن في تحريم النبي - صلى الله عليه وسلم - تضييع حق متعلق به للغير، وهو حق الجارية. وليس ذلك في فعل إسرائيل، وأيضا فإن\n⟦2:719⟧\nإسرائيل لما حرم أشهى الطعام إليه قصد بذلك قمع الشهوة، وبنحو\nذلك يهذب الحكيم نفسه، والنبي - صلى الله عليه وسلم - في تحريم جاريته تبع هوى غيره، وهو مرضاة أزواجه، وذلك مكروه، فلم يقر عليه،\n⟦2:720⟧\nذكر بعض الصوفية أن في ذلك تفضيلا للنبي - صلى الله عليه وسلم - من وجهين.\n⟦2:721⟧\nأحدهما: أنه لما حرم إسرائيل على نفسه ما أحبه أمضاه، وحرم\nالنبي - صلى الله عليه وسلم - على نفسه فعافاه.\nوالثاني: أن بني إسرائيل ما كانوا يلتزمونه مما لم يكن قربة في الشريعة يلزمهم الوفاء به تشديدا عليهم، وعلى ذلك دل قوله: ﴿مَا كَتَبۡنَٰهَا عَلَيۡهِمۡ إِلَّا ٱبۡتِغَآءَ رِضۡوَٰنِ ٱللَّهِ﴾⟪57:27⟫\nوقال - صلى الله عليه وسلم -: \"شددوا على أنفسهم فشدد الله\nعليهم \"، ورفع عن هذه الأمة ذلك فضيلة للنبي - صلى الله عليه وسلم -. إن قيل: ما وجه اتصال هذه الآيات بعضها ببعض، لأنه ذكر أولا:\n﴿إِنَّ ٱلَّذِينَ كَفَرُواْ بَعۡدَ إِيمَٰنِهِمۡ﴾⟪3:90⟫ الآيتين ثم ذكر: ﴿لَن تَنَالُواْ ٱلۡبِرَّ حَتَّىٰ تُنفِقُواْ مِمَّا تُحِبُّونَۚ﴾⟪3:92⟫ ثم عقبها بتحريم إسرائيل الطعام، وذم اليهود؟\n⟦2:722⟧\nقيل: لما ذكر في الآيتين المتقدمتين ذم اليهود وغيرهم من الكفار.\nوبين أن انفافهم مع كفرهم غير مقبول منهم، وصل ذلك بقوله:\n﴿لَن تَنَالُواْ ٱلۡبِرَّ﴾⟪3:92⟫، لئلا يقرر أن الانفاق غير مغن على جميع\nالوجوه، فقال: وأنتم أيها المؤمنون إذا أنفقتم فإنما نقبل منكم\nعلى هذا الشرط، ثم رجع إلى ذم اليهود وتعديد ما ارتكبوه.\nفصار قوله: ﴿لَن تَنَالُواْ ٱلۡبِرَّ﴾⟪3:92⟫ بين الآيتين من الاعتراض\nالمسمى في كتب البلاغة الالتفات."}, {"a": [94], "v": 2, "p": 722, "ev": 2, "ep": 723, "sid": 924, "t": "قوله تعالى: (فمن افترى على الله الكذب من بعد ذلك فأولئك هم الظالمون (94)\n⟦2:723⟧\nالافتراء والاختلاق: افتعال للكذب الذي لا أصل له، من افتراء الأديم واختلاقه.\nوالكذب ضربان:\nاختراع قصة لا أصل لها وزيادة، أو تغيير فيما له أصل.\nوالأول أعظمهما، والمفترى عليه ضربان: رفيع ووضيع.\nفالمفتري على الرفيع أعظم ذنبا، ثم المفتري له ضربان: عارف بالفرية.\nوجاهل بها، فالمفتري العارف بالفرية أوقحهما وجها، فبين الله\nتعالى بالآية أنهم اختلقوا الكذب على الله تعالى، الذي يعلم السر\nوأخفى، وفعلوا ذلك بعد أن أطلع الله الناس على كذبهم ، وبين\nأن متخذي ذلك في نهاية الظلم، وعلى ذلك في غير موضع:\n﴿وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا﴾."}, {"a": [95], "v": 2, "p": 723, "ev": 2, "ep": 724, "sid": 925, "t": "قوله تعالى: (قل صدق الله فاتبعوا ملة إبراهيم حنيفا وما كان من المشركين (95)\n⟦2:724⟧\nمعنى قوله: قل اعتقد وأخبر أن ذلك من قول الله\nتعالى، وهو صادق. وحقيقة قوله: ﴿صَدَقَ ٱللَّهُۗ﴾⟪3:95⟫ إقرار بأن الله\nقد أخبر، فإنه إذا ثبت كونه من خبره ثبت. كونه صدقا، ونبه أن\nما أخبر من قوله: ﴿كُلُّ ٱلطَّعَامِ كَانَ حِلّٗا﴾⟪3:93⟫ وسائر ما تقدم\nصدق، وأنه ملة إبراهيم، وأوجب عليهم اتباعه في تحنفه أي\nفي استقامته، وفي قوله: ﴿وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ﴾⟪3:95⟫ تعريض بهم.\nكأنه قيل: أنتم مشركون في اتخاذ بعضكم بعضا أربابا، وإبراهيم لم\nيكن مشركا، فإذن ليس دينكم دين إبراهيم، وكما نفى في\nقوله: ﴿مَا كَانَ إِبۡرَٰهِيمُ يَهُودِيّٗا وَلَا نَصۡرَانِيّٗا﴾⟪3:67⟫ أنه منهم نفى في هذه\nالآية كونه مشركا."}];
